		private static List<MEPCurve> CollectMepCurves(Document doc, bool useDucts, bool usePipes, bool useTrays, bool selectedOnly, bool currentViewOnly, List<MEPCurve> preselected)
		{
			List<MEPCurve> list = new List<MEPCurve>();
			if (selectedOnly)
			{
				foreach (MEPCurve current in preselected)
				{
					if (current is Duct & useDucts)
					{
						list.Add(current);
					}
					else
					{
						if (current is Pipe & usePipes)
						{
							list.Add(current);
						}
						else
						{
							if (current is CableTray & useTrays)
							{
								list.Add(current);
							}
						}
					}
				}
				return list;
			}
			ElementId elementId = currentViewOnly ? doc.ActiveView.Id : null;
			if (useDucts)
			{
				FilteredElementCollector filteredElementCollector = (elementId != null) ? new FilteredElementCollector(doc, elementId) : new FilteredElementCollector(doc);
				list.AddRange(filteredElementCollector.OfClass(typeof(Duct)).Cast<MEPCurve>());
			}
			if (usePipes)
			{
				FilteredElementCollector filteredElementCollector2 = (elementId != null) ? new FilteredElementCollector(doc, elementId) : new FilteredElementCollector(doc);
				list.AddRange(filteredElementCollector2.OfClass(typeof(Pipe)).Cast<MEPCurve>());
			}
			if (useTrays)
			{
				FilteredElementCollector filteredElementCollector3 = (elementId != null) ? new FilteredElementCollector(doc, elementId) : new FilteredElementCollector(doc);
				list.AddRange(filteredElementCollector3.OfClass(typeof(CableTray)).Cast<MEPCurve>());
			}
			return list;
		}
