		private void UpdateParamLists()
		{
			if (this._comboFamily == null || this._comboWidth == null || this._comboHeight == null || this._comboDepth == null)
			{
				return;
			}
			FamilySelectionWindow.SymbolItem symbolItem = this._comboFamily.SelectedItem as FamilySelectionWindow.SymbolItem;
			if (symbolItem == null || symbolItem.Symbol == null)
			{
				return;
			}
			List<string> list;
			try
			{
				list = DuctWallOpeningsCommand.GetEditableDoubleParamNames(this._doc, symbolItem.Symbol);
			}
			catch
			{
				list = new List<string>();
			}
			List<string> list2 = new List<string>
			{
				"— не задавать —"
			};
			list2.AddRange(list);
			this._comboWidth.ItemsSource = list2.ToList<string>();
			this._comboHeight.ItemsSource = list2.ToList<string>();
			this._comboDepth.ItemsSource = list2.ToList<string>();
			this._comboWidth.SelectedItem = (this.FindByKeywords(list, new string[]
			{
				"ширин",
				"width"
			}) ?? list2[0]);
			this._comboHeight.SelectedItem = (this.FindByKeywords(list, new string[]
			{
				"высот",
				"height"
			}) ?? list2[0]);
			this._comboDepth.SelectedItem = (this.FindByKeywords(list, new string[]
			{
				"глубин",
				"толщин",
				"depth",
				"thick"
			}) ?? list2[0]);
		}
		private string FindByKeywords(List<string> names, params string[] keys)
		{
			for (int i = 0; i < keys.Length; i++)
			{
				string key = keys[i];
				string text = names.FirstOrDefault((string n) => n.ToLower().Contains(key));
				if (text != null)
				{
					return text;
				}
			}
			return null;
		}
		private void OkBtn_Click(object sender, RoutedEventArgs e)
		{
			FamilySelectionWindow.SymbolItem symbolItem = this._comboFamily.SelectedItem as FamilySelectionWindow.SymbolItem;
			if (symbolItem == null)
			{
				System.Windows.MessageBox.Show("Выберите семейство.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			this.SelectedSymbol = symbolItem.Symbol;
			this.WidthParam = this.NormalizeParam(this._comboWidth.SelectedItem as string);
			this.HeightParam = this.NormalizeParam(this._comboHeight.SelectedItem as string);
			this.DepthParam = this.NormalizeParam(this._comboDepth.SelectedItem as string);
			double num;
			if (double.TryParse(this._offsetBox.Text.Replace('.', ','), out num) && num >= 0.0)
			{
				this.OffsetMm = num;
			}
			else
			{
				this.OffsetMm = 50.0;
			}
			double num2;
			if (double.TryParse(this._depthOffsetBox.Text.Replace('.', ','), out num2) && num2 >= 0.0)
			{
				this.DepthOffsetMm = num2;
			}
			else
			{
				this.DepthOffsetMm = 50.0;
			}
			System.Windows.Controls.CheckBox expr_111 = this._chkSelectedOnly;
			this.UseSelectedOnly = (expr_111 != null && expr_111.IsChecked.GetValueOrDefault());
			System.Windows.Controls.CheckBox expr_132 = this._chkCurrentView;
			this.UseCurrentViewOnly = (expr_132 != null && expr_132.IsChecked.GetValueOrDefault());
			System.Windows.Controls.CheckBox expr_153 = this._chkDucts;
			this.UseDucts = (expr_153 != null && expr_153.IsChecked.GetValueOrDefault());
			System.Windows.Controls.CheckBox expr_174 = this._chkPipes;
			this.UsePipes = (expr_174 != null && expr_174.IsChecked.GetValueOrDefault());
			System.Windows.Controls.CheckBox expr_195 = this._chkTrays;
			this.UseTrays = (expr_195 != null && expr_195.IsChecked.GetValueOrDefault());
			System.Windows.Controls.CheckBox expr_1B6 = this._chkMergeOpenings;
			this.MergeOpenings = (expr_1B6 != null && expr_1B6.IsChecked.GetValueOrDefault());
			double num3;
			if (this._txtMergeDistance != null && double.TryParse(this._txtMergeDistance.Text.Replace('.', ','), out num3) && num3 >= 0.0)
			{
				this.MergeDistanceMm = num3;
			}
			else
			{
				this.MergeDistanceMm = 200.0;
			}
			base.DialogResult = new bool?(true);
			base.Close();
		}
		private string NormalizeParam(string s)
		{
			if (string.IsNullOrEmpty(s) || s == "— не задавать —")
			{
				return null;
			}
			return s;
		}
