		private void SelectBtn_Click(object sender, RoutedEventArgs e)
		{
			this.ResultAction = MergeAction.ManualPick;
			base.DialogResult = new bool?(true);
			base.Close();
		}
		private void BatchBtn_Click(object sender, RoutedEventArgs e)
		{
			MergeOpeningsWindow.SymbolItem symbolItem = this._comboSourceFamily.SelectedItem as MergeOpeningsWindow.SymbolItem;
			if (symbolItem == null)
			{
				System.Windows.MessageBox.Show("Выберите семейство для объединения в Варианте 2.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			this.SourceSymbol = symbolItem.Symbol;
			this.SelectedSymbol = symbolItem.Symbol;
			string widthParam;
			string heightParam;
			string depthParam;
			OpeningsRunner.AutoDetectParamNames(this._doc, this.SourceSymbol, null, null, null, out widthParam, out heightParam, out depthParam);
			this.WidthParam = widthParam;
			this.HeightParam = heightParam;
			this.DepthParam = depthParam;
			this.OffsetMm = 0.0;
			this.DepthOffsetMm = 0.0;
			double num;
			if (double.TryParse(this._txtMergeDistance.Text.Replace('.', ','), out num) && num >= 0.0)
			{
				this.MergeDistanceMm = num;
				System.Windows.Controls.CheckBox expr_DC = this._chkCurrentView;
				this.UseCurrentViewOnly = (expr_DC != null && expr_DC.IsChecked.GetValueOrDefault());
				this.ResultAction = MergeAction.BatchMerge;
				base.DialogResult = new bool?(true);
				base.Close();
				return;
			}
			System.Windows.MessageBox.Show("Некорректное значение расстояния.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
		}
	}
