		private static ExcelTable ParseTsvToExcelTable(string filePath, string sheetName, bool preserveFormatting)
		{
			ExcelTable excelTable = new ExcelTable
			{
				SheetName = sheetName
			};
			if (!File.Exists(filePath))
			{
				return excelTable;
			}
			string[] array = File.ReadAllLines(filePath, Encoding.Unicode);
			if (array.Length == 0)
			{
				return excelTable;
			}
			int i = 0;
			bool flag = false;
			string text = "";
			if (array.Length > 2 && string.IsNullOrEmpty(array[1].Trim()))
			{
				text = array[0].Trim().Trim(new char[]
				{
					'"'
				});
				flag = true;
				i = 2;
			}
			if (i < array.Length)
			{
				string line = array[i++];
				excelTable.Headers = ExcelExportCommand.ParseTsvLine(line);
			}
			while (i < array.Length)
			{
				string text2 = array[i++];
				if (!string.IsNullOrEmpty(text2.Trim()))
				{
					List<string> arg_B3_0 = ExcelExportCommand.ParseTsvLine(text2);
					List<object> list = new List<object>();
					foreach (string current in arg_B3_0)
					{
						double num;
						if (double.TryParse(current, NumberStyles.Any, CultureInfo.InvariantCulture, out num))
						{
							list.Add(num);
						}
						else
						{
							double num2;
							if (double.TryParse(current.Replace(",", "."), NumberStyles.Any, CultureInfo.InvariantCulture, out num2))
							{
								list.Add(num2);
							}
							else
							{
								list.Add(current);
							}
						}
					}
					excelTable.Rows.Add(list);
				}
			}
			if (flag && !string.IsNullOrEmpty(text))
			{
				excelTable.Title = text;
			}
			return excelTable;
		}
		private static List<string> ParseTsvLine(string line)
		{
			List<string> list = new List<string>();
			string[] array = line.Split(new char[]
			{
				'\t'
			});
			for (int i = 0; i < array.Length; i++)
			{
				string text = array[i];
				list.Add(text.Trim().Trim(new char[]
				{
					'"'
				}));
			}
			return list;
		}
	}
