		private void CbSets_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			if (this._isUpdatingUi || this._cbSets.SelectedIndex == -1)
			{
				return;
			}
			this._isUpdatingUi = true;
			string selectedSetName = this._cbSets.SelectedItem as string;
			ScheduleSet scheduleSet = this._settings.Sets.FirstOrDefault((ScheduleSet s) => s.Name == selectedSetName);
			if (scheduleSet != null)
			{
				foreach (ScheduleExportItem current in this._allSchedules)
				{
					current.IsChecked = scheduleSet.SelectedScheduleNames.Contains(current.ScheduleName);
				}
				this._settings.SelectedSet = selectedSetName;
				this._settings.Save();
			}
			this._isUpdatingUi = false;
			this.UpdateSelectedCount();
		}
