		private void BtnEditSet_Click(object sender, RoutedEventArgs e)
		{
			string selectedSetName = this._cbSets.SelectedItem as string;
			if (string.IsNullOrEmpty(selectedSetName))
			{
				return;
			}
			InputPromptWindow inputPromptWindow = new InputPromptWindow("Переименовать набор", "Введите новое имя набора:", selectedSetName);
			inputPromptWindow.Owner = this;
			if (inputPromptWindow.ShowDialog().GetValueOrDefault())
			{
				string newName = inputPromptWindow.InputText;
				if (this._settings.Sets.Any((ScheduleSet s) => s.Name.Equals(newName, StringComparison.OrdinalIgnoreCase)))
				{
					System.Windows.MessageBox.Show("Набор с таким именем уже существует.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
					return;
				}
				ScheduleSet scheduleSet = this._settings.Sets.FirstOrDefault((ScheduleSet s) => s.Name == selectedSetName);
				if (scheduleSet != null)
				{
					scheduleSet.Name = newName;
					this._settings.SelectedSet = newName;
					this._settings.Save();
					this._isUpdatingUi = true;
					this.LoadSets();
					this._isUpdatingUi = false;
				}
			}
		}
		private void BtnDeleteSet_Click(object sender, RoutedEventArgs e)
		{
			string selectedSetName = this._cbSets.SelectedItem as string;
			if (string.IsNullOrEmpty(selectedSetName))
			{
				return;
			}
			if (System.Windows.MessageBox.Show("Вы уверены, что хотите удалить набор '" + selectedSetName + "'?", "Удаление набора", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes)
			{
				ScheduleSet scheduleSet = this._settings.Sets.FirstOrDefault((ScheduleSet s) => s.Name == selectedSetName);
				if (scheduleSet != null)
				{
					this._settings.Sets.Remove(scheduleSet);
					this._settings.SelectedSet = "";
					this._settings.Save();
					this._isUpdatingUi = true;
					this.LoadSets();
					this._cbSets.SelectedIndex = -1;
					this._isUpdatingUi = false;
				}
			}
		}
