				this._txtFolder.Text = exportConfig.ExportFolder;
				this._chkSeparate.IsChecked = new bool?(exportConfig.EachScheduleInSeparateFile);
				this._txtPrefix.Text = exportConfig.FilePrefix;
				this._txtFileName.Text = exportConfig.FileName;
				this._chkHeader.IsChecked = new bool?(exportConfig.ExportHeader);
				this._chkFormatting.IsChecked = new bool?(exportConfig.PreserveFormatting);
				this._settings.SelectedConfig = selectedConfigName;
				this._settings.Save();
				this.ToggleFileNameField();
			}
			this._isUpdatingUi = false;
		}
		private void BtnAddConfig_Click(object sender, RoutedEventArgs e)
		{
			InputPromptWindow inputPromptWindow = new InputPromptWindow("Создать конфигурацию", "Введите имя новой конфигурации:", "");
			inputPromptWindow.Owner = this;
			if (inputPromptWindow.ShowDialog().GetValueOrDefault())
			{
				string name = inputPromptWindow.InputText;
				if (this._settings.Configs.Any((ExportConfig c) => c.Name.Equals(name, StringComparison.OrdinalIgnoreCase)))
				{
					System.Windows.MessageBox.Show("Конфигурация с таким именем уже существует.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
					return;
				}
				ExportConfig item = new ExportConfig
				{
					Name = name,
					ExportFolder = this._txtFolder.Text,
					EachScheduleInSeparateFile = this._chkSeparate.IsChecked.GetValueOrDefault(),
					FilePrefix = this._txtPrefix.Text,
					FileName = this._txtFileName.Text,
					ExportHeader = this._chkHeader.IsChecked.GetValueOrDefault(),
					PreserveFormatting = this._chkFormatting.IsChecked.GetValueOrDefault()
				};
				this._settings.Configs.Add(item);
				this._settings.SelectedConfig = name;
				this._settings.Save();
				this._isUpdatingUi = true;
				this.LoadConfigs();
				this._isUpdatingUi = false;
			}
		}
		private void BtnEditConfig_Click(object sender, RoutedEventArgs e)
		{
			string selectedConfigName = this._cbConfigs.SelectedItem as string;
			if (string.IsNullOrEmpty(selectedConfigName))
			{
				return;
			}
			InputPromptWindow inputPromptWindow = new InputPromptWindow("Переименовать конфигурацию", "Введите новое имя конфигурации:", selectedConfigName);
			inputPromptWindow.Owner = this;
			if (inputPromptWindow.ShowDialog().GetValueOrDefault())
			{
				string newName = inputPromptWindow.InputText;
				if (this._settings.Configs.Any((ExportConfig c) => c.Name.Equals(newName, StringComparison.OrdinalIgnoreCase)))
				{
					System.Windows.MessageBox.Show("Конфигурация с таким именем уже существует.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
					return;
				}
				ExportConfig exportConfig = this._settings.Configs.FirstOrDefault((ExportConfig c) => c.Name == selectedConfigName);
				if (exportConfig != null)
				{
					exportConfig.Name = newName;
					this._settings.SelectedConfig = newName;
					this._settings.Save();
					this._isUpdatingUi = true;
					this.LoadConfigs();
					this._isUpdatingUi = false;
				}
			}
		}
		private void BtnDeleteConfig_Click(object sender, RoutedEventArgs e)
		{
			string selectedConfigName = this._cbConfigs.SelectedItem as string;
			if (string.IsNullOrEmpty(selectedConfigName))
			{
				return;
			}
			if (System.Windows.MessageBox.Show("Вы уверены, что хотите удалить конфигурацию '" + selectedConfigName + "'?", "Удаление конфигурации", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes)
			{
				ExportConfig exportConfig = this._settings.Configs.FirstOrDefault((ExportConfig c) => c.Name == selectedConfigName);
				if (exportConfig != null)
				{
					this._settings.Configs.Remove(exportConfig);
					this._settings.SelectedConfig = "";
					this._settings.Save();
					this._isUpdatingUi = true;
					this.LoadConfigs();
					this._cbConfigs.SelectedIndex = -1;
					this._isUpdatingUi = false;
				}
			}
		}
		private void BtnBrowse_Click(object sender, RoutedEventArgs e)
		{
			using (FolderBrowserDialog folderBrowserDialog = new FolderBrowserDialog())
			{
				folderBrowserDialog.Description = "Выберите папку для экспорта спецификаций";
				if (folderBrowserDialog.ShowDialog() == System.Windows.Forms.DialogResult.OK)
				{
					this._txtFolder.Text = folderBrowserDialog.SelectedPath;
				}
			}
		}
		private void SaveCurrentSettingsToActiveConfig()
		{
			this._settings.ExportFolder = this._txtFolder.Text;
			this._settings.EachScheduleInSeparateFile = this._chkSeparate.IsChecked.GetValueOrDefault();
			this._settings.FilePrefix = this._txtPrefix.Text;
			this._settings.FileName = this._txtFileName.Text;
			this._settings.ExportHeader = this._chkHeader.IsChecked.GetValueOrDefault();
			this._settings.PreserveFormatting = this._chkFormatting.IsChecked.GetValueOrDefault();
			string selectedConfigName = this._cbConfigs.SelectedItem as string;
			if (!string.IsNullOrEmpty(selectedConfigName))
			{
				ExportConfig exportConfig = this._settings.Configs.FirstOrDefault((ExportConfig c) => c.Name == selectedConfigName);
				if (exportConfig != null)
				{
					exportConfig.ExportFolder = this._txtFolder.Text;
					exportConfig.EachScheduleInSeparateFile = this._chkSeparate.IsChecked.GetValueOrDefault();
					exportConfig.FilePrefix = this._txtPrefix.Text;
					exportConfig.FileName = this._txtFileName.Text;
					exportConfig.ExportHeader = this._chkHeader.IsChecked.GetValueOrDefault();
					exportConfig.PreserveFormatting = this._chkFormatting.IsChecked.GetValueOrDefault();
				}
			}
			this._settings.Save();
		}
		private void BtnExportCurrent_Click(object sender, RoutedEventArgs e)
		{
			this.SaveCurrentSettingsToActiveConfig();
			this.ExportCurrentOnly = true;
			base.DialogResult = new bool?(true);
			base.Close();
		}
		private void BtnExportAll_Click(object sender, RoutedEventArgs e)
		{
			if (this.SelectedSchedules.Count == 0)
			{
				System.Windows.MessageBox.Show("Пожалуйста, выберите хотя бы одну спецификацию для экспорта.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			if (string.IsNullOrEmpty(this._txtFolder.Text) || !Directory.Exists(this._txtFolder.Text))
			{
				System.Windows.MessageBox.Show("Указанная папка экспорта не существует. Пожалуйста, выберите папку.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			this.SaveCurrentSettingsToActiveConfig();
			this.ExportCurrentOnly = false;
			base.DialogResult = new bool?(true);
			base.Close();
		}
	}
