		public ExcelTable()
		{
			this.<Title>k__BackingField = "";
			this.<Headers>k__BackingField = new List<string>();
			this.<Rows>k__BackingField = new List<List<object>>();
			this.<NumericSumColumns>k__BackingField = new HashSet<int>();
			base..ctor();
		}
	}
	public static class ExcelWriter
	{
		public static void Write(string filePath, List<ExcelTable> tables)
		{
			using (FileStream fileStream = new FileStream(filePath, FileMode.Create, FileAccess.Write, FileShare.None))
			{
				using (StreamWriter streamWriter = new StreamWriter(fileStream, Encoding.UTF8))
				{
					streamWriter.WriteLine("<?xml version=\"1.0\" encoding=\"utf-8\"?>");
					streamWriter.WriteLine("<?mso-application progid=\"Excel.Sheet\"?>");
					streamWriter.WriteLine("<Workbook xmlns=\"urn:schemas-microsoft-com:office:spreadsheet\"");
					streamWriter.WriteLine(" xmlns:o=\"urn:schemas-microsoft-com:office:office\"");
					streamWriter.WriteLine(" xmlns:x=\"urn:schemas-microsoft-com:office:excel\"");
					streamWriter.WriteLine(" xmlns:ss=\"urn:schemas-microsoft-com:office:spreadsheet\"");
					streamWriter.WriteLine(" xmlns:html=\"http://www.w3.org/TR/REC-html40\">");
					streamWriter.WriteLine(" <DocumentProperties xmlns=\"urn:schemas-microsoft-com:office:office\">");
					streamWriter.WriteLine("  <Author>BimboClub Tools</Author>");
					streamWriter.WriteLine("  <Created>" + DateTime.UtcNow.ToString("yyyy-MM-ddTHH:mm:ssZ") + "</Created>");
					streamWriter.WriteLine(" </DocumentProperties>");
					streamWriter.WriteLine(" <Styles>");
					streamWriter.WriteLine("  <Style ss:ID=\"Default\" ss:Name=\"Normal\">");
					streamWriter.WriteLine("   <Alignment ss:Vertical=\"Center\"/>");
					streamWriter.WriteLine("   <Font ss:FontName=\"Segoe UI\" ss:Size=\"10\" ss:Color=\"#333333\"/>");
					streamWriter.WriteLine("  </Style>");
					streamWriter.WriteLine("  <Style ss:ID=\"TitleStyle\">");
					streamWriter.WriteLine("   <Font ss:FontName=\"Segoe UI\" ss:Size=\"14\" ss:Bold=\"1\" ss:Color=\"#B30E2D\"/>");
					streamWriter.WriteLine("   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Center\"/>");
					streamWriter.WriteLine("  </Style>");
					streamWriter.WriteLine("  <Style ss:ID=\"Header\">");
					streamWriter.WriteLine("   <Font ss:FontName=\"Segoe UI\" ss:Size=\"10\" ss:Bold=\"1\" ss:Color=\"#FFFFFF\"/>");
					streamWriter.WriteLine("   <Interior ss:Color=\"#B30E2D\" ss:Pattern=\"Solid\"/>");
					streamWriter.WriteLine("   <Alignment ss:Horizontal=\"Center\" ss:Vertical=\"Center\" ss:WrapText=\"1\"/>");
					streamWriter.WriteLine("   <Borders>");
					streamWriter.WriteLine("    <Border ss:Position=\"Bottom\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\" ss:Color=\"#7A091E\"/>");
					streamWriter.WriteLine("    <Border ss:Position=\"Left\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\" ss:Color=\"#D26D7E\"/>");
					streamWriter.WriteLine("    <Border ss:Position=\"Right\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\" ss:Color=\"#D26D7E\"/>");
					streamWriter.WriteLine("   </Borders>");
					streamWriter.WriteLine("  </Style>");
					streamWriter.WriteLine("  <Style ss:ID=\"Zebra\">");
					streamWriter.WriteLine("   <Interior ss:Color=\"#F8F9FA\" ss:Pattern=\"Solid\"/>");
					streamWriter.WriteLine("   <Alignment ss:Vertical=\"Center\"/>");
					streamWriter.WriteLine("  </Style>");
					streamWriter.WriteLine("  <Style ss:ID=\"Summary\">");
					streamWriter.WriteLine("   <Font ss:FontName=\"Segoe UI\" ss:Size=\"10\" ss:Bold=\"1\" ss:Color=\"#000000\"/>");
					streamWriter.WriteLine("   <Interior ss:Color=\"#E9ECEF\" ss:Pattern=\"Solid\"/>");
					streamWriter.WriteLine("   <Borders>");
					streamWriter.WriteLine("    <Border ss:Position=\"Top\" ss:LineStyle=\"Continuous\" ss:Weight=\"1\" ss:Color=\"#CCCCCC\"/>");
					streamWriter.WriteLine("    <Border ss:Position=\"Bottom\" ss:LineStyle=\"Double\" ss:Weight=\"2\" ss:Color=\"#333333\"/>");
					streamWriter.WriteLine("   </Borders>");
					streamWriter.WriteLine("   <Alignment ss:Vertical=\"Center\"/>");
					streamWriter.WriteLine("  </Style>");
					streamWriter.WriteLine(" </Styles>");
					foreach (ExcelTable current in tables)
					{
						string str = ExcelWriter.EscapeXmlAttribute(current.SheetName);
						streamWriter.WriteLine(" <Worksheet ss:Name=\"" + str + "\">");
						streamWriter.WriteLine("  <Table>");
						int count = current.Headers.Count;
						double[] array = new double[count];
						for (int i = 0; i < count; i++)
						{
							array[i] = Math.Max(100.0, (double)current.Headers[i].Length * 8.5);
						}
						foreach (List<object> current2 in current.Rows)
						{
							for (int j = 0; j < Math.Min(count, current2.Count); j++)
							{
								if (current2[j] != null)
								{
									string text = current2[j].ToString();
									array[j] = Math.Max(array[j], (double)text.Length * 7.5);
								}
							}
						}
						for (int k = 0; k < count; k++)
						{
							streamWriter.WriteLine(string.Format("   <Column ss:Width=\"{0}\"/>", Math.Min(350.0, array[k])));
						}
						if (!string.IsNullOrEmpty(current.Title))
						{
							streamWriter.WriteLine("   <Row ss:Height=\"30\">");
							int num = Math.Max(0, count - 1);
							streamWriter.WriteLine(string.Format("    <Cell ss:MergeAcross=\"{0}\" ss:StyleID=\"TitleStyle\"><Data ss:Type=\"String\">{1}</Data></Cell>", num, ExcelWriter.EscapeXmlText(current.Title)));
							streamWriter.WriteLine("   </Row>");
							streamWriter.WriteLine("   <Row ss:Height=\"10\"></Row>");
						}
						streamWriter.WriteLine("   <Row ss:Height=\"26\">");
						for (int l = 0; l < count; l++)
						{
							string str2 = ExcelWriter.EscapeXmlText(current.Headers[l]);
							streamWriter.WriteLine("    <Cell ss:StyleID=\"Header\"><Data ss:Type=\"String\">" + str2 + "</Data></Cell>");
						}
						streamWriter.WriteLine("   </Row>");
						for (int m = 0; m < current.Rows.Count; m++)
						{
							List<object> list = current.Rows[m];
							bool flag = false;
							foreach (object current3 in list)
							{
								if (current3 != null)
								{
									string text2 = current3.ToString().Trim().ToLower();
									if (text2.StartsWith("итого") || text2.StartsWith("всего") || text2.StartsWith("total"))
									{
										flag = true;
										break;
									}
								}
							}
							string str3 = flag ? " ss:StyleID=\"Summary\"" : ((m % 2 != 0) ? " ss:StyleID=\"Zebra\"" : "");
							streamWriter.WriteLine("   <Row ss:Height=\"20\"" + str3 + ">");
							for (int n = 0; n < count; n++)
							{
								object val = (n < list.Count) ? list[n] : null;
								ExcelWriter.WriteCell(streamWriter, val);
							}
							streamWriter.WriteLine("   </Row>");
						}
						if (current.Rows.Count > 0 && current.NumericSumColumns.Count > 0)
						{
							streamWriter.WriteLine("   <Row ss:Height=\"24\" ss:StyleID=\"Summary\">");
							for (int num2 = 0; num2 < count; num2++)
							{
								if (num2 == 0)
								{
									streamWriter.WriteLine("    <Cell><Data ss:Type=\"String\">ИТОГО:</Data></Cell>");
								}
								else
								{
									if (current.NumericSumColumns.Contains(num2))
									{
										int count2 = current.Rows.Count;
										streamWriter.WriteLine(string.Format("    <Cell ss:Formula=\"=SUM(R[-{0}]C:R[-1]C)\"><Data ss:Type=\"Number\">0</Data></Cell>", count2));
									}
									else
									{
										streamWriter.WriteLine("    <Cell><Data ss:Type=\"String\"></Data></Cell>");
									}
								}
							}
							streamWriter.WriteLine("   </Row>");
						}
						streamWriter.WriteLine("  </Table>");
						streamWriter.WriteLine(" </Worksheet>");
					}
					streamWriter.WriteLine("</Workbook>");
				}
			}
		}
		private static void WriteCell(StreamWriter writer, object val)
		{
			if (val == null)
			{
				writer.WriteLine("    <Cell><Data ss:Type=\"String\"></Data></Cell>");
				return;
			}
			if (val is int || val is long || val is short || val is byte)
			{
				writer.WriteLine(string.Format("    <Cell><Data ss:Type=\"Number\">{0}</Data></Cell>", val));
				return;
			}
			if (val is double)
			{
				writer.WriteLine("    <Cell><Data ss:Type=\"Number\">" + ((double)val).ToString(CultureInfo.InvariantCulture) + "</Data></Cell>");
				return;
			}
			if (val is float)
			{
				writer.WriteLine("    <Cell><Data ss:Type=\"Number\">" + ((float)val).ToString(CultureInfo.InvariantCulture) + "</Data></Cell>");
				return;
			}
			if (val is decimal)
			{
				writer.WriteLine("    <Cell><Data ss:Type=\"Number\">" + ((decimal)val).ToString(CultureInfo.InvariantCulture) + "</Data></Cell>");
				return;
			}
			if (val is bool)
			{
				bool flag = (bool)val;
				writer.WriteLine("    <Cell><Data ss:Type=\"String\">" + (flag ? "Да" : "Нет") + "</Data></Cell>");
				return;
			}
			string text = val.ToString() ?? string.Empty;
			writer.WriteLine("    <Cell><Data ss:Type=\"String\">" + ExcelWriter.EscapeXmlText(text) + "</Data></Cell>");
		}
		private static string EscapeXmlText(string text)
		{
			if (string.IsNullOrEmpty(text))
			{
				return string.Empty;
			}
			return text.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;");
		}
		private static string EscapeXmlAttribute(string text)
		{
			if (string.IsNullOrEmpty(text))
			{
				return string.Empty;
			}
			return text.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;").Replace("\"", "&quot;").Replace("'", "&apos;");
		}
	}
