	[Transaction(TransactionMode.Manual)]
	public class HeatLossCommand : IExternalCommand
	{
		public Result Execute(ExternalCommandData commandData, ref string message, ElementSet elements)
		{
			UIApplication application = commandData.Application;
			UIDocument activeUIDocument = application.ActiveUIDocument;
			Document doc = (activeUIDocument != null) ? activeUIDocument.Document : null;
			Document expr_33 = doc;
			Autodesk.Revit.DB.View view = (expr_33 != null) ? expr_33.ActiveView : null;
			if (doc == null || view == null)
			{
				message = "Не найден активный вид или документ.";
				return Result.Failed;
			}
			Result result;
			try
			{
				Logger.Log("Запуск команды расчета теплопотерь.", "INFO");
				List<SpatialElement> list = new FilteredElementCollector(doc, view.Id).OfCategory(BuiltInCategory.OST_Rooms).Cast<SpatialElement>().ToList<SpatialElement>();
				if (list.Count == 0)
				{
					list = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Rooms).Cast<SpatialElement>().ToList<SpatialElement>();
				}
				if (list.Count == 0)
				{
					TaskDialog.Show("Внимание", "В проекте не найдено помещений (Rooms) для расчета теплопотерь.");
					result = Result.Cancelled;
				}
				else
				{
					List<RoomHeatLossItem> list2 = new List<RoomHeatLossItem>();
					foreach (SpatialElement current in list)
					{
						Parameter expr_103 = current.get_Parameter(BuiltInParameter.ROOM_AREA);
						double num = (expr_103 != null) ? expr_103.AsDouble() : 0.0;
						Parameter expr_126 = current.get_Parameter(BuiltInParameter.ROOM_VOLUME);
						double arg_151_0 = (expr_126 != null) ? expr_126.AsDouble() : 0.0;
						double num2 = num * 0.092903;
						double value = arg_151_0 * 0.0283168;
						if (num2 > 0.0)
						{
							list2.Add(new RoomHeatLossItem
							{
								Number = current.Number,
								Name = current.Name,
								Area = Math.Round(num2, 2),
								Volume = Math.Round(value, 2),
								RawRoom = current
							});
						}
					}
					if (list2.Count == 0)
					{
						TaskDialog.Show("Внимание", "Найденные помещения имеют нулевую площадь. Проверьте границы помещений.");
						result = Result.Cancelled;
					}
					else
					{
						List<string> writableRoomDoubleParameters = HeatLossCommand.GetWritableRoomDoubleParameters(doc);
						HeatLossWindow window = new HeatLossWindow(list2, writableRoomDoubleParameters);
						new WindowInteropHelper(window).Owner = application.MainWindowHandle;
						window.CalculateRequested += delegate
						{
							this.PerformCalculation(window, doc);
						};
						window.WriteToRevitRequested += delegate
						{
							this.WriteBackToRevit(window, doc);
						};
						window.ExportExcelRequested += delegate
						{
							this.ExportToExcel(window, doc);
						};
						this.PerformCalculation(window, doc);
						window.ShowDialog();
						result = Result.Succeeded;
					}
				}
			}
			catch (Exception ex)
			{
				Logger.LogError("Ошибка в команде расчета теплопотерь", ex);
				message = ex.Message + "\n" + ex.StackTrace;
				result = Result.Failed;
			}
			return result;
		}
		private static List<string> GetWritableRoomDoubleParameters(Document doc)
		{
			List<string> list = new List<string>();
			Element element = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Rooms).FirstOrDefault<Element>();
			if (element != null)
			{
				foreach (Parameter parameter in element.Parameters)
				{
					if (parameter.StorageType == StorageType.Double && !parameter.IsReadOnly)
					{
						list.Add(parameter.Definition.Name);
					}
				}
			}
			if (!list.Contains("Теплопотери"))
			{
				list.Insert(0, "Теплопотери");
			}
			return list.Distinct<string>().ToList<string>();
		}
		private void PerformCalculation(HeatLossWindow window, Document doc)
		{
			double arg_0E_0 = window.TempIndoor;
