					double area = current.Area;
					double volume = current.Volume;
					double num2 = 0.0;
					IList<IList<BoundarySegment>> boundarySegments = spatialElement.GetBoundarySegments(options);
					if (boundarySegments != null)
					{
						using (IEnumerator<IList<BoundarySegment>> enumerator2 = boundarySegments.GetEnumerator())
						{
							while (enumerator2.MoveNext())
