										double num5 = (expr_FE != null) ? expr_FE.AsDouble() : 0.0;
										if (num5 > 0.0)
										{
											num4 = num5 * 0.3048;
										}
									}
									catch
									{
									}
									double num6 = num3 * num4;
									ElementId elementId = ElementId.InvalidElementId;
									try
									{
										PropertyInfo property = current2.GetType().GetProperty("ElementId");
										if (property != null)
										{
											elementId = (property.GetValue(current2) as ElementId);
										}
