											num7 = uWindow;
										}
										else
										{
											if (text.Contains("двер") || text.Contains("door"))
											{
												num7 = uDoor;
											}
											else
											{
												if (text.Contains("перекрыт") || text.Contains("roof") || text.Contains("крыш"))
