			RoomHeatLossItem expr_2B = window.Rooms.FirstOrDefault<RoomHeatLossItem>();
			SpatialElement spatialElement = ((expr_2B != null) ? expr_2B.RawRoom : null) as SpatialElement;
			if (spatialElement == null)
			{
				return;
			}
			Parameter parameter = spatialElement.LookupParameter(selectedParameter);
			if (parameter == null)
			{
				TaskDialog.Show("Внимание", "Параметр с именем '" + selectedParameter + "' не найден у помещений. Запись невозможна. Убедитесь, что параметр добавлен к категории Помещения.");
				return;
			}
			if (parameter.IsReadOnly)
			{
				TaskDialog.Show("Ошибка", "Параметр '" + selectedParameter + "' доступен только для чтения.");
				return;
			}
			using (Transaction transaction = new Transaction(doc, "Запись теплопотерь BimboClub"))
			{
				transaction.Start();
				int num = 0;
				foreach (RoomHeatLossItem current in window.Rooms)
				{
					SpatialElement spatialElement2 = current.RawRoom as SpatialElement;
					if (spatialElement2 != null)
					{
						Parameter parameter2 = spatialElement2.LookupParameter(selectedParameter);
						if (parameter2 != null)
						{
							parameter2.Set(current.TotalLoss);
							num++;
						}
					}
				}
				transaction.Commit();
				TaskDialog.Show("Успех", string.Format("Теплопотери успешно записаны в параметр '{0}' для {1} помещений.", selectedParameter, num));
			}
		}
		private void ExportToExcel(HeatLossWindow window, Document doc)
		{
			using (System.Windows.Forms.SaveFileDialog saveFileDialog = new System.Windows.Forms.SaveFileDialog
			{
				Title = "Экспорт теплопотерь в Excel - BimboClub Tools",
				Filter = "Excel Workbook (*.xml)|*.xml|Excel 97-2003 (*.xls)|*.xls",
				FileName = string.Concat(doc.Title.Split(System.IO.Path.GetInvalidFileNameChars())).Trim() + "_Теплопотери.xls",
				DefaultExt = "xls",
				AddExtension = true
			})
			{
				if (saveFileDialog.ShowDialog() == DialogResult.OK)
				{
					ExcelTable excelTable = new ExcelTable
					{
						SheetName = "Расчет теплопотерь"
					};
					excelTable.Headers = new List<string>
					{
						"Номер помещения",
						"Имя помещения",
						"Площадь (м²)",
						"Объем (м³)",
						"Трансмиссия (Вт)",
						"Вентиляция (Вт)",
						"Теплопотери всего (Вт)"
					};
					excelTable.NumericSumColumns.Add(2);
					excelTable.NumericSumColumns.Add(3);
					excelTable.NumericSumColumns.Add(4);
					excelTable.NumericSumColumns.Add(5);
					excelTable.NumericSumColumns.Add(6);
					foreach (RoomHeatLossItem current in window.Rooms)
					{
						excelTable.Rows.Add(new List<object>
						{
							current.Number,
							current.Name,
							current.Area,
							current.Volume,
							current.TransmissionLoss,
							current.VentilationLoss,
							current.TotalLoss
						});
					}
					ExcelWriter.Write(saveFileDialog.FileName, new List<ExcelTable>
					{
						excelTable
					});
					TaskDialog.Show("Успех", "Данные расчета теплопотерь успешно экспортированы в:\n" + saveFileDialog.FileName);
				}
			}
		}
	}
