			FrameworkElementFactory frameworkElementFactory2 = new FrameworkElementFactory(typeof(ContentPresenter));
			frameworkElementFactory2.SetValue(FrameworkElement.HorizontalAlignmentProperty, System.Windows.HorizontalAlignment.Center);
			frameworkElementFactory2.SetValue(FrameworkElement.VerticalAlignmentProperty, VerticalAlignment.Center);
			frameworkElementFactory.AppendChild(frameworkElementFactory2);
			controlTemplate.VisualTree = frameworkElementFactory;
			arg_E5_0.Setters.Add(new Setter(System.Windows.Controls.Control.TemplateProperty, controlTemplate));
			return arg_E5_0;
		}
		private void ApplyButtonStyles(System.Windows.Controls.Button btn, LinearGradientBrush normalGrad, LinearGradientBrush hoverGrad, Style roundedStyle)
		{
			btn.Style = roundedStyle;
			btn.Background = normalGrad;
			btn.MouseEnter += delegate(object s, System.Windows.Input.MouseEventArgs e)
			{
				if (btn.IsEnabled)
				{
					btn.Background = hoverGrad;
				}
			};
			btn.MouseLeave += delegate(object s, System.Windows.Input.MouseEventArgs e)
			{
				if (btn.IsEnabled)
				{
					btn.Background = normalGrad;
				}
			};
		}
		private void ApplyFlatButtonStyles(System.Windows.Controls.Button btn, SolidColorBrush normalBrush, SolidColorBrush hoverBrush, Style roundedStyle)
		{
			btn.Style = roundedStyle;
			btn.Background = normalBrush;
			btn.MouseEnter += delegate(object s, System.Windows.Input.MouseEventArgs e)
			{
				if (btn.IsEnabled)
				{
					btn.Background = hoverBrush;
				}
			};
			btn.MouseLeave += delegate(object s, System.Windows.Input.MouseEventArgs e)
			{
				if (btn.IsEnabled)
				{
					btn.Background = normalBrush;
				}
			};
		}
