		private static System.Drawing.Image _btnGearImage = null;
		private static bool _imagesLoaded = false;
		public Result Execute(ExternalCommandData commandData, ref string message, ElementSet elements)
		{
			Result result;
			try
			{
				string text = System.IO.Path.Combine(System.IO.Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location), "LTools.dll");
				if (!File.Exists(text))
				{
					TaskDialog.Show("Ошибка", "Файл LTools.dll не найден в папке плагина:\n" + text);
					result = Result.Failed;
				}
				else
				{
					Type type = Assembly.LoadFrom(text).GetType("SAV.ParamRules.CmdRuler");
					if (type == null)
					{
						TaskDialog.Show("Ошибка", "Не найден класс SAV.ParamRules.CmdRuler в LTools.dll");
						result = Result.Failed;
					}
					else
					{
						IExternalCommand externalCommand = Activator.CreateInstance(type) as IExternalCommand;
						if (externalCommand == null)
						{
							TaskDialog.Show("Ошибка", "Класс SAV.ParamRules.CmdRuler не реализует интерфейс IExternalCommand");
							result = Result.Failed;
						}
						else
						{
							System.Windows.Forms.Timer timer = new System.Windows.Forms.Timer();
							timer.Interval = 50;
							int inactiveCount = 0;
							timer.Tick += delegate(object sender, EventArgs ev)
							{
								try
								{
									bool flag = false;
									List<System.Windows.Forms.Form> list = new List<System.Windows.Forms.Form>();
									foreach (System.Windows.Forms.Form item in System.Windows.Forms.Application.OpenForms)
									{
										list.Add(item);
									}
									foreach (System.Windows.Forms.Form current in list)
									{
										if (current.GetType().Namespace != null && current.GetType().Namespace.StartsWith("SAV.ParamRules"))
										{
											flag = true;
											LToolsRulesCommand.StyleControl(current);
										}
									}
									if (flag)
									{
										int inactiveCount = 0;
									}
									else
									{
										int inactiveCount = inactiveCount;
										inactiveCount++;
										if (inactiveCount > 100)
										{
											timer.Stop();
											timer.Dispose();
										}
									}
								}
								catch
								{
								}
							};
							timer.Start();
							result = externalCommand.Execute(commandData, ref message, elements);
						}
					}
				}
			}
			catch (Exception ex)
			{
				Logger.LogError("Ошибка при вызове редактора правил LTools", ex);
				message = ex.Message;
				result = Result.Failed;
			}
			return result;
		}
