		private void PopulateSheetSets()
		{
			this._cbSheetSets.Items.Clear();
			this._cbSheetSets.Items.Add("<Выбрать сохраненный набор...>");
			this._cbSheetSets.Items.Add("<Все листы>");
			if (!string.IsNullOrEmpty(this._activeSheetNumber))
			{
				this._cbSheetSets.Items.Add("<Активный лист>");
			}
			if (this._sheetSetMap != null)
			{
				foreach (string current in this._sheetSetMap.Keys)
				{
					this._cbSheetSets.Items.Add(current);
				}
			}
			this._cbSheetSets.SelectedIndex = 0;
			this._cbSheetSets.SelectionChanged += new SelectionChangedEventHandler(this.CbSheetSets_SelectionChanged);
		}
		private void CbSheetSets_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			if (this._cbSheetSets.SelectedIndex <= 0)
			{
				return;
			}
			string text = this._cbSheetSets.SelectedItem.ToString();
			if (text == "<Все листы>")
			{
				using (List<SheetItem>.Enumerator enumerator = this._allSheets.GetEnumerator())
				{
					while (enumerator.MoveNext())
					{
						enumerator.Current.IsChecked = true;
					}
					goto IL_119;
				}
			}
			if (text == "<Активный лист>")
			{
				using (List<SheetItem>.Enumerator enumerator = this._allSheets.GetEnumerator())
				{
					while (enumerator.MoveNext())
					{
						SheetItem expr_86 = enumerator.Current;
						expr_86.IsChecked = (expr_86.SheetNumber == this._activeSheetNumber);
					}
					goto IL_119;
				}
			}
			if (this._sheetSetMap != null && this._sheetSetMap.ContainsKey(text))
			{
				List<string> list = this._sheetSetMap[text];
				foreach (SheetItem current in this._allSheets)
				{
					current.IsChecked = list.Contains(current.SheetNumber);
				}
			}
			IL_119:
			this.RefreshList();
		}
		private void SetAllSelection(bool isSelected)
		{
			using (List<SheetItem>.Enumerator enumerator = this._allSheets.GetEnumerator())
			{
				while (enumerator.MoveNext())
				{
					enumerator.Current.IsChecked = isSelected;
				}
			}
			this.RefreshList();
		}
		private void RefreshList()
		{
