			{
				list = (
					from s in this._allSheets
					where (s.SheetNumber != null && s.SheetNumber.IndexOf(filter, StringComparison.OrdinalIgnoreCase) >= 0) || (s.SheetName != null && s.SheetName.IndexOf(filter, StringComparison.OrdinalIgnoreCase) >= 0)
					select s).ToList<SheetItem>();
