		private void UpdateNamingPreview()
		{
			if (this._txtNamingPreview == null || this._txtNamingPattern == null)
			{
				return;
			}
			string text = this._txtNamingPattern.Text;
			string str;
			if (this._chkCombine != null && this._chkCombine.IsChecked.GetValueOrDefault())
			{
				str = text.Replace("{ProjectNumber}", this._sampleProjNum).Replace("{Section}", this._sampleSection).Replace("{SheetNumber}", "Комплект").Replace("{SheetName}", "Чертежей");
			}
			else
			{
				str = text.Replace("{ProjectNumber}", this._sampleProjNum).Replace("{Section}", this._sampleSection).Replace("{SheetNumber}", "01").Replace("{SheetName}", "План_1_этажа");
			}
			this._txtNamingPreview.Text = "Превью имени: " + str + ".pdf";
		}
		private void BtnBrowse_Click(object sender, RoutedEventArgs e)
		{
			using (FolderBrowserDialog folderBrowserDialog = new FolderBrowserDialog())
			{
				folderBrowserDialog.Description = "Выберите папку для сохранения экспортированных PDF чертежей";
				folderBrowserDialog.ShowNewFolderButton = true;
				if (folderBrowserDialog.ShowDialog() == System.Windows.Forms.DialogResult.OK)
				{
					this._txtFolderPath.Text = folderBrowserDialog.SelectedPath;
				}
			}
		}
		private void BtnExport_Click(object sender, RoutedEventArgs e)
		{
			if (this.SelectedSheets.Count == 0)
			{
				System.Windows.MessageBox.Show("Пожалуйста, выберите хотя бы один лист для экспорта.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			if (string.IsNullOrWhiteSpace(this._txtFolderPath.Text) || !Directory.Exists(this._txtFolderPath.Text))
			{
				System.Windows.MessageBox.Show("Пожалуйста, выберите существующую папку для сохранения файлов.", "Ошибка", MessageBoxButton.OK, MessageBoxImage.Hand);
				return;
			}
			this.IsExportRequested = true;
			base.DialogResult = new bool?(true);
			base.Close();
		}
	}
