	[Transaction(TransactionMode.Manual)]
	public class RouterCommand : IExternalCommand
	{
		public Result Execute(ExternalCommandData commandData, ref string message, ElementSet elements)
		{
			UIApplication application = commandData.Application;
			UIDocument activeUIDocument = application.ActiveUIDocument;
			Document document = activeUIDocument.Document;
			Result result;
			try
			{
				Logger.Log("Запуск команды Умная трассировка (BimboClub Router).", "INFO");
				Element selectedMepElem = null;
				Selection selection = activeUIDocument.Selection;
				ICollection<ElementId> elementIds = selection.GetElementIds();
				if (elementIds.Count == 1)
				{
					Element element = document.GetElement(elementIds.First<ElementId>());
					if (element is Duct || element is Pipe)
					{
						selectedMepElem = element;
					}
				}
				if (selectedMepElem == null)
				{
					try
					{
						Reference reference = selection.PickObject(ObjectType.Element, new MepElementSelectionFilter(), "Пожалуйста, выберите воздуховод или трубу для построения обхода");
						selectedMepElem = document.GetElement(reference);
					}
					catch (Autodesk.Revit.Exceptions.OperationCanceledException)
					{
						Logger.Log("Выбор элемента отменен пользователем.", "INFO");
						result = Result.Cancelled;
						return result;
					}
				}
				if (selectedMepElem == null)
				{
					TaskDialog.Show("Внимание", "Не выбран корректный MEP элемент (воздуховод или труба).");
					result = Result.Cancelled;
				}
				else
				{
					RouterWindow routerWindow = new RouterWindow();
					new WindowInteropHelper(routerWindow).Owner = application.MainWindowHandle;
					if (!routerWindow.ShowDialog().GetValueOrDefault() || !routerWindow.IsExecutionRequested)
					{
						Logger.Log("Выполнение команды отменено в интерфейсе.", "INFO");
						result = Result.Cancelled;
					}
					else
					{
						string selectedDirection = routerWindow.SelectedDirection;
						double selectedAngle = routerWindow.SelectedAngle;
						double num = routerWindow.ClearanceMm / 304.8;
						double num2 = routerWindow.OffsetMm / 304.8;
						bool searchInLinks = routerWindow.SearchInLinks;
						LocationCurve locationCurve = selectedMepElem.Location as LocationCurve;
						if (locationCurve == null || !(locationCurve.Curve is Autodesk.Revit.DB.Line))
						{
							TaskDialog.Show("Ошибка", "Выбранный элемент не имеет прямой осевой линии.");
							result = Result.Failed;
						}
						else
						{
							Autodesk.Revit.DB.Line line = locationCurve.Curve as Autodesk.Revit.DB.Line;
							XYZ endPoint = line.GetEndPoint(0);
							XYZ endPoint2 = line.GetEndPoint(1);
							XYZ xYZ = (endPoint2 - endPoint).Normalize();
							double num3 = endPoint.DistanceTo(endPoint2);
							XYZ xYZ2 = endPoint + xYZ * (num3 / 2.0);
							double num4 = 0.65616797900262469;
							bool flag = false;
							try
							{
								List<ObstacleInfo> list = this.FindObstacles(document, line, searchInLinks);
								if (list.Count > 0)
								{
									XYZ xYZ3;
									double num5;
									flag = this.GetClashGeometry(line, list, out xYZ3, out num5);
									if (flag)
									{
										xYZ2 = xYZ3;
										num4 = num5;
										Logger.Log(string.Format("Найдена коллизия в точке {0}, ширина препятствия: {1} мм.", xYZ2, num4 * 304.8), "INFO");
									}
								}
							}
							catch (Exception ex)
							{
								Logger.LogError("Ошибка при поиске коллизий, используем центральную точку", ex);
							}
							if (!flag)
							{
								Logger.Log("Коллизии не обнаружены. Будет построен дефолтный обход в центре элемента.", "INFO");
							}
							XYZ left = XYZ.BasisZ;
							if (selectedDirection == "DOWN")
							{
								left = -XYZ.BasisZ;
							}
							else
							{
								if (selectedDirection == "LEFT" || selectedDirection == "RIGHT")
								{
									XYZ xYZ4 = xYZ.CrossProduct(XYZ.BasisZ);
									if (xYZ4.IsZeroLength())
									{
										xYZ4 = XYZ.BasisX;
									}
									else
									{
