			if (this.OffsetMm <= 0.0)
			{
				System.Windows.MessageBox.Show("Пожалуйста, укажите положительную высоту смещения.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			this.IsExecutionRequested = true;
			base.DialogResult = new bool?(true);
			base.Close();
		}
