	[Transaction(TransactionMode.Manual)]
	public class SizerCommand : IExternalCommand
	{
		public Result Execute(ExternalCommandData commandData, ref string message, ElementSet elements)
		{
			UIApplication application = commandData.Application;
			UIDocument activeUIDocument = application.ActiveUIDocument;
			Document document = activeUIDocument.Document;
			Result result;
			try
			{
				Logger.Log("Запуск команды Расчет сечений (Sizer).", "INFO");
				IEnumerable<ElementId> arg_35_0 = activeUIDocument.Selection.GetElementIds();
				List<MEPCurve> list = new List<MEPCurve>();
				foreach (ElementId current in arg_35_0)
				{
					MEPCurve mEPCurve = document.GetElement(current) as MEPCurve;
					if (mEPCurve != null)
					{
						list.Add(mEPCurve);
					}
				}
				bool flag = list.Count > 0;
				string categoryName = "";
				double initialFlow = 0.0;
				double initialSizeVal = 0.0;
				double initialSizeVal2 = 0.0;
				if (flag)
				{
					MEPCurve mEPCurve2 = list.First<MEPCurve>();
					categoryName = mEPCurve2.Category.Name;
					Parameter parameter = null;
					if (mEPCurve2 is Duct)
					{
						parameter = mEPCurve2.get_Parameter(BuiltInParameter.RBS_DUCT_FLOW_PARAM);
					}
					else
					{
						if (mEPCurve2 is Pipe)
						{
							parameter = mEPCurve2.get_Parameter(BuiltInParameter.RBS_PIPE_FLOW_PARAM);
						}
					}
					if (parameter != null && parameter.HasValue)
					{
						double num = parameter.AsDouble();
						if (mEPCurve2 is Duct)
						{
							initialFlow = num * 101.940647;
						}
						else
						{
							initialFlow = num * 28.3168466;
						}
					}
					Duct duct = mEPCurve2 as Duct;
					if (duct != null)
					{
						Parameter parameter2 = duct.get_Parameter(BuiltInParameter.RBS_CURVE_DIAMETER_PARAM);
						Parameter parameter3 = duct.get_Parameter(BuiltInParameter.RBS_CURVE_WIDTH_PARAM);
						Parameter parameter4 = duct.get_Parameter(BuiltInParameter.RBS_CURVE_HEIGHT_PARAM);
						if (parameter2 != null && parameter2.HasValue)
						{
							initialSizeVal = parameter2.AsDouble() * 304.8;
						}
						else
						{
							if (parameter3 != null && parameter4 != null && parameter3.HasValue && parameter4.HasValue)
							{
								initialSizeVal = parameter3.AsDouble() * 304.8;
								initialSizeVal2 = parameter4.AsDouble() * 304.8;
							}
						}
					}
					else
					{
						Pipe pipe = mEPCurve2 as Pipe;
						if (pipe != null)
						{
							Parameter parameter5 = pipe.get_Parameter(BuiltInParameter.RBS_CURVE_DIAMETER_PARAM);
							if (parameter5 != null)
							{
								initialSizeVal = parameter5.AsDouble() * 304.8;
							}
						}
					}
				}
				SizerWindow sizerWindow = new SizerWindow(flag, categoryName, initialFlow, initialSizeVal, initialSizeVal2);
				new WindowInteropHelper(sizerWindow).Owner = application.MainWindowHandle;
				if ((sizerWindow.ShowDialog().GetValueOrDefault() && sizerWindow.IsApplied) & flag)
				{
					int num2 = 0;
					using (Transaction transaction = new Transaction(document, "Расчет сечений BimboClub"))
					{
						transaction.Start();
						foreach (MEPCurve current2 in list)
						{
							try
							{
								Duct duct2 = current2 as Duct;
								if (duct2 != null)
								{
									Parameter parameter6 = duct2.get_Parameter(BuiltInParameter.RBS_CURVE_DIAMETER_PARAM);
									Parameter parameter7 = duct2.get_Parameter(BuiltInParameter.RBS_CURVE_WIDTH_PARAM);
									Parameter parameter8 = duct2.get_Parameter(BuiltInParameter.RBS_CURVE_HEIGHT_PARAM);
									if (parameter6 != null && !parameter6.IsReadOnly && sizerWindow.FinalDiameter > 0.0)
									{
										parameter6.Set(sizerWindow.FinalDiameter / 304.8);
										num2++;
									}
									else
									{
										if (parameter7 != null && !parameter7.IsReadOnly && parameter8 != null && !parameter8.IsReadOnly && sizerWindow.FinalWidth > 0.0 && sizerWindow.FinalHeight > 0.0)
										{
											parameter7.Set(sizerWindow.FinalWidth / 304.8);
											parameter8.Set(sizerWindow.FinalHeight / 304.8);
											num2++;
										}
									}
								}
								else
								{
									Pipe pipe2 = current2 as Pipe;
									if (pipe2 != null && sizerWindow.FinalDiameter > 0.0)
									{
										Parameter parameter9 = pipe2.get_Parameter(BuiltInParameter.RBS_CURVE_DIAMETER_PARAM);
										if (parameter9 != null && !parameter9.IsReadOnly)
										{
											parameter9.Set(sizerWindow.FinalDiameter / 304.8);
											num2++;
										}
									}
								}
							}
							catch (Exception ex)
							{
								Logger.LogError(string.Format("Не удалось изменить размер элемента {0}", current2.Id), ex);
							}
						}
						transaction.Commit();
					}
					Logger.Log(string.Format("Успешно пересчитаны сечения для элементов: {0} из {1}.", num2, list.Count), "INFO");
					TaskDialog.Show("Успех", string.Format("Сечения успешно пересчитаны!\nИзменено элементов: {0} из {1}", num2, list.Count));
				}
				result = Result.Succeeded;
			}
			catch (Exception ex2)
			{
				Logger.LogError("Ошибка во время выполнения SizerCommand", ex2);
				message = ex2.Message + "\n" + ex2.StackTrace;
				result = Result.Failed;
			}
			return result;
		}
	}
