		private void SetSystemType(SizerWindow.SystemType sysType)
		{
			this._currentSystemType = sysType;
			if (this._currentSystemType == SizerWindow.SystemType.Duct)
			{
				this._lblFlowUnit.Content = "м³/ч";
				this._lblVelUnit.Content = "м/с";
				this._sliderVelocity.Minimum = 1.0;
				this._sliderVelocity.Maximum = 12.0;
				if (this._sliderVelocity.Value < 1.0 || this._sliderVelocity.Value > 12.0)
				{
					this._sliderVelocity.Value = 4.0;
				}
				this._rbRect.IsEnabled = true;
			}
			else
			{
				this._lblFlowUnit.Content = "л/с";
				this._lblVelUnit.Content = "м/с";
				this._sliderVelocity.Minimum = 0.1;
				this._sliderVelocity.Maximum = 3.0;
				if (this._sliderVelocity.Value < 0.1 || this._sliderVelocity.Value > 3.0)
				{
					this._sliderVelocity.Value = 1.0;
				}
				this._rbRound.IsChecked = new bool?(true);
				this._rbRect.IsEnabled = false;
				this.SetShapeType(SizerWindow.ShapeType.Round);
			}
			this.PopulateDiameterComboBox();
			this.Recalculate();
		}
		private void SetShapeType(SizerWindow.ShapeType shapeType)
		{
			this._currentShapeType = shapeType;
			if (this._currentShapeType == SizerWindow.ShapeType.Round)
			{
				this._txtCalcDiameter.Visibility = System.Windows.Visibility.Visible;
				this._cbStdDiameter.Visibility = System.Windows.Visibility.Visible;
				this._rectGrid.Visibility = System.Windows.Visibility.Collapsed;
			}
			else
			{
				this._txtCalcDiameter.Visibility = System.Windows.Visibility.Collapsed;
				this._cbStdDiameter.Visibility = System.Windows.Visibility.Collapsed;
				this._rectGrid.Visibility = System.Windows.Visibility.Visible;
				this.UpdateRectLabels();
			}
			this.Recalculate();
		}
		private void UpdateRectLabels()
		{
			if (this._rbLockWidth.IsChecked.GetValueOrDefault())
			{
				this._lblLockDim.Content = "Ширина зафиксир. (A):";
				this._lblFreeDim.Content = "Высота расчетная (B):";
				return;
			}
			this._lblLockDim.Content = "Высота зафиксир. (B):";
			this._lblFreeDim.Content = "Ширина расчетная (A):";
		}
		private void PopulateDiameterComboBox()
		{
			this._cbStdDiameter.Items.Clear();
			this._cbStdFreeDimension.Items.Clear();
			List<int> list;
			if (this._currentSystemType == SizerWindow.SystemType.Duct)
			{
				list = new List<int>
				{
					100,
					125,
					150,
					160,
					200,
					250,
					315,
					355,
					400,
					450,
					500,
					560,
					630,
					710,
					800,
					900,
					1000,
					1120,
					1250
				};
			}
			else
			{
				list = new List<int>
				{
					10,
					15,
					20,
					25,
					32,
					40,
					50,
					65,
					80,
					100,
					125,
					150,
					200,
					250,
					300
				};
			}
			foreach (int current in list)
			{
				this._cbStdDiameter.Items.Add(current.ToString());
				this._cbStdFreeDimension.Items.Add(current.ToString());
			}
		}
		private void SliderVelocity_ValueChanged(object sender, RoutedPropertyChangedEventArgs<double> e)
		{
			if (this._txtVelocity != null)
			{
				this._txtVelocity.Text = this._sliderVelocity.Value.ToString("F1");
				this.Recalculate();
			}
		}
		private void TxtVelocity_TextChanged(object sender, TextChangedEventArgs e)
		{
			double num;
			if (double.TryParse(this._txtVelocity.Text, out num) && num >= this._sliderVelocity.Minimum && num <= this._sliderVelocity.Maximum)
			{
				this._sliderVelocity.Value = num;
				this.Recalculate();
			}
		}
		private void Recalculate()
		{
			if (this._txtFlow == null || this._txtVelocity == null)
			{
				return;
			}
			double num;
			if (!double.TryParse(this._txtFlow.Text, out num) || num <= 0.0)
			{
				return;
			}
			double num2;
			if (!double.TryParse(this._txtVelocity.Text, out num2) || num2 <= 0.0)
			{
				return;
			}
			if (this._currentSystemType == SizerWindow.SystemType.Duct)
			{
				double num3 = num / 3600.0 / num2;
				if (this._currentShapeType == SizerWindow.ShapeType.Round)
				{
					double num4 = Math.Sqrt(4.0 * num3 / 3.1415926535897931) * 1000.0;
					this._txtCalcDiameter.Text = string.Format("{0:F1} мм", num4);
					int num5 = 100;
					IEnumerator enumerator = ((IEnumerable)this._cbStdDiameter.Items).GetEnumerator();
					try
					{
						while (enumerator.MoveNext())
						{
							int num6 = int.Parse(enumerator.Current.ToString());
							if ((double)num6 >= num4)
							{
								num5 = num6;
								break;
							}
							num5 = num6;
						}
					}
					finally
					{
						IDisposable disposable = enumerator as IDisposable;
						if (disposable != null)
						{
							disposable.Dispose();
						}
					}
					this._cbStdDiameter.Text = num5.ToString();
				}
				else
				{
					double num7;
					if (!double.TryParse(this._txtLockedDimension.Text, out num7) || num7 <= 0.0)
					{
						return;
					}
					double num8 = num3 / (num7 / 1000.0) * 1000.0;
					this._txtCalcFreeDimension.Text = string.Format("{0:F1} мм", num8);
					int num9 = 100;
					IEnumerator enumerator = ((IEnumerable)this._cbStdFreeDimension.Items).GetEnumerator();
					try
					{
						while (enumerator.MoveNext())
						{
							int num10 = int.Parse(enumerator.Current.ToString());
							if ((double)num10 >= num8)
							{
								num9 = num10;
								break;
							}
							num9 = num10;
						}
