		private Definition GetOrCreateTemporarySharedParameter(Autodesk.Revit.ApplicationServices.Application app, string name, string fopDataTypeString, out string error)
		{
			error = null;
			string text = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "BimboClub_Temp_FOP.txt");
			string sharedParametersFilename = app.SharedParametersFilename;
			Definition result;
			try
			{
				if (!File.Exists(text))
				{
					string[] contents = new string[]
					{
						"# This is a Revit shared parameter file.",
						"# Do not edit manually.",
						"*META\tVERSION\tMINVERSION",
						"META\t2\t1",
						"*GROUP\tID\tNAME",
						"GROUP\t1\tBimboClub Project Parameters",
						"*PARAM\tGUID\tNAME\tDATATYPE\tDATACATEGORY\tGROUP\tVISIBLE\tDESCRIPTION\tUSERMODIFIABLE"
					};
					File.WriteAllLines(text, contents, Encoding.UTF8);
				}
				app.SharedParametersFilename = text;
				DefinitionFile definitionFile = app.OpenSharedParameterFile();
				if (definitionFile == null)
				{
					throw new System.InvalidOperationException("Не удалось открыть временный файл ФОП.");
				}
				DefinitionGroup definitionGroup = definitionFile.Groups.get_Item("BimboClub Project Parameters");
				if (definitionGroup == null)
				{
					definitionGroup = definitionFile.Groups.Create("BimboClub Project Parameters");
				}
				Definition definition = definitionGroup.Definitions.get_Item(name);
				if (definition != null)
				{
					result = definition;
				}
				else
				{
					ForgeTypeId dataType = SpecTypeId.String.Text;
					if (fopDataTypeString == "TEXT")
					{
						dataType = SpecTypeId.String.Text;
					}
					else
					{
						if (fopDataTypeString == "LENGTH")
						{
							dataType = SpecTypeId.Length;
						}
						else
						{
							if (fopDataTypeString == "INTEGER")
							{
								dataType = SpecTypeId.Int.Integer;
							}
							else
							{
								if (fopDataTypeString == "ANGLE")
								{
									dataType = SpecTypeId.Angle;
								}
								else
								{
									if (fopDataTypeString == "NUMBER")
									{
										dataType = SpecTypeId.Number;
									}
									else
									{
										if (fopDataTypeString == "YESNO")
										{
											dataType = SpecTypeId.Boolean.YesNo;
										}
									}
								}
							}
						}
					}
					ExternalDefinitionCreationOptions option = new ExternalDefinitionCreationOptions(name, dataType);
					definition = definitionGroup.Definitions.Create(option);
					result = definition;
				}
			}
			catch (Exception ex)
			{
				error = ex.Message;
				result = null;
			}
			finally
			{
				app.SharedParametersFilename = sharedParametersFilename;
			}
			return result;
		}
	}
	public class BimboFamilyLoadOptions : IFamilyLoadOptions
	{
		public bool OnFamilyFound(bool familyInUse, out bool overwriteParameterValues)
		{
			overwriteParameterValues = true;
			return true;
		}
		public bool OnSharedFamilyFound(Family sharedFamily, bool familyInUse, out FamilySource source, out bool overwriteParameterValues)
		{
			source = FamilySource.Family;
			overwriteParameterValues = true;
			return true;
		}
	}
