		private void LoadDefaultSettings()
		{
			try
			{
				string sharedParametersFilename = this._doc.Application.SharedParametersFilename;
				if (!string.IsNullOrEmpty(sharedParametersFilename) && File.Exists(sharedParametersFilename))
				{
					this._txtFopPath.Text = sharedParametersFilename;
					this.LoadFopData(sharedParametersFilename);
				}
			}
			catch (Exception ex)
