		private void BtnBrowseFop_Click(object sender, RoutedEventArgs e)
		{
			Microsoft.Win32.OpenFileDialog openFileDialog = new Microsoft.Win32.OpenFileDialog
			{
				Filter = "Файлы общих параметров (*.txt)|*.txt",
				Title = "Выберите файл общих параметров (ФОП)"
			};
			if (openFileDialog.ShowDialog().GetValueOrDefault())
			{
				this._txtFopPath.Text = openFileDialog.FileName;
				this.LoadFopData(openFileDialog.FileName);
			}
		}
		private void LoadFopData(string fopPath)
		{
			try
			{
				string sharedParametersFilename = this._doc.Application.SharedParametersFilename;
				this._doc.Application.SharedParametersFilename = fopPath;
				DefinitionFile definitionFile = this._doc.Application.OpenSharedParameterFile();
				if (definitionFile == null)
				{
					this._doc.Application.SharedParametersFilename = sharedParametersFilename;
					System.Windows.MessageBox.Show("Не удалось открыть или прочитать выбранный файл ФОП.", "Ошибка", MessageBoxButton.OK, MessageBoxImage.Hand);
				}
				else
				{
					List<FopDefinitionGroupItem> list = new List<FopDefinitionGroupItem>();
					foreach (DefinitionGroup current in definitionFile.Groups)
					{
						FopDefinitionGroupItem fopDefinitionGroupItem = new FopDefinitionGroupItem
						{
							Name = current.Name
						};
						foreach (Definition current2 in current.Definitions)
						{
							fopDefinitionGroupItem.Parameters.Add(new FopDefinitionItem
							{
								Name = current2.Name,
								Definition = current2
							});
						}
						if (fopDefinitionGroupItem.Parameters.Count > 0)
						{
							list.Add(fopDefinitionGroupItem);
						}
					}
					this._doc.Application.SharedParametersFilename = sharedParametersFilename;
					this._cbFopGroup.ItemsSource = list;
					if (list.Count > 0)
					{
						this._cbFopGroup.SelectedIndex = 0;
					}
					else
					{
						this._cbFopGroup.ItemsSource = null;
						this._cbFopParam.ItemsSource = null;
					}
				}
			}
			catch (Exception ex)
			{
				System.Windows.MessageBox.Show("Ошибка при анализе файла ФОП:\n" + ex.Message, "Ошибка", MessageBoxButton.OK, MessageBoxImage.Hand);
			}
		}
		private void CbFopGroup_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			FopDefinitionGroupItem fopDefinitionGroupItem = this._cbFopGroup.SelectedItem as FopDefinitionGroupItem;
			if (fopDefinitionGroupItem != null)
			{
				this._cbFopParam.ItemsSource = fopDefinitionGroupItem.Parameters;
				if (fopDefinitionGroupItem.Parameters.Count > 0)
				{
					this._cbFopParam.SelectedIndex = 0;
					return;
				}
			}
			else
			{
				this._cbFopParam.ItemsSource = null;
			}
		}
