					Logger.Log(string.Format("Пользователь выбрал {0} систем для генерации 3D схем.", selectedSystems.Count), "INFO");
					int num = 0;
					using (Transaction transaction = new Transaction(document, "Создание 3D схем"))
					{
						transaction.Start();
						SchemeGenerator schemeGenerator = new SchemeGenerator(document);
						foreach (SystemItem current2 in selectedSystems)
						{
							if (current2.ElementCount != 0)
							{
								schemeGenerator.GenerateForSystem(current2.Name, systemSelectionWindow.ViewPrefix, systemSelectionWindow.ViewSuffix, systemSelectionWindow.ViewParameters, systemSelectionWindow.SelectedFilterParamId);
								num++;
							}
						}
						transaction.Commit();
					}
					Logger.Log(string.Format("Успешно создано видов: {0} из {1}.", num, selectedSystems.Count), "INFO");
					TaskDialog.Show("Успех", string.Format("Обработка завершена!\nУспешно создано 3D-видов: {0} из {1}", num, selectedSystems.Count));
					result = Result.Succeeded;
				}
			}
			catch (Exception ex2)
			{
				Logger.LogError("Ошибка при выполнении 3D Scheme", ex2);
				message = ex2.Message + "\n" + ex2.StackTrace;
				result = Result.Failed;
			}
			return result;
		}
		private static ElementId FindParameterIdByName(Document doc, string paramName, List<ElementId> categories)
		{
			try
			{
				ElementMulticategoryFilter filter = new ElementMulticategoryFilter(categories);
				foreach (Element current in new FilteredElementCollector(doc).WherePasses(filter).WhereElementIsNotElementType().ToList<Element>())
				{
					Parameter parameter = current.LookupParameter(paramName);
					if (parameter != null)
					{
						ElementId id = parameter.Id;
						return id;
					}
					ElementId typeId = current.GetTypeId();
					if (typeId != ElementId.InvalidElementId)
					{
						Element expr_7B = doc.GetElement(typeId);
						Parameter parameter2 = (expr_7B != null) ? expr_7B.LookupParameter(paramName) : null;
						if (parameter2 != null)
						{
							ElementId id = parameter2.Id;
							return id;
						}
					}
				}
				SharedParameterElement sharedParameterElement = new FilteredElementCollector(doc).OfClass(typeof(SharedParameterElement)).Cast<SharedParameterElement>().FirstOrDefault((SharedParameterElement p) => p.Name.Equals(paramName, StringComparison.OrdinalIgnoreCase));
				if (sharedParameterElement != null)
				{
					ElementId id = sharedParameterElement.Id;
					return id;
				}
			}
			catch (Exception ex)
			{
				Logger.LogError("Ошибка при поиске ID параметра " + paramName, ex);
			}
			return ElementId.InvalidElementId;
		}
		private List<Element> GetElementsInSystem(Document doc, MEPSystem system)
		{
			List<Element> list = new List<Element>();
			foreach (Element element in system.Elements)
			{
				if (element != null)
				{
					list.Add(element);
				}
			}
			if (list.Count > 0)
			{
				return list;
			}
			string name = system.Name;
			foreach (Element current in new FilteredElementCollector(doc).WherePasses(new ElementMulticategoryFilter(new List<BuiltInCategory>
			{
				BuiltInCategory.OST_DuctCurves,
				BuiltInCategory.OST_PlaceHolderDucts,
				BuiltInCategory.OST_DuctFitting,
				BuiltInCategory.OST_DuctAccessory,
				BuiltInCategory.OST_DuctTerminal,
				BuiltInCategory.OST_PipeCurves,
				BuiltInCategory.OST_PlaceHolderPipes,
				BuiltInCategory.OST_PipeFitting,
				BuiltInCategory.OST_PipeAccessory,
				BuiltInCategory.OST_MechanicalEquipment,
				BuiltInCategory.OST_PlumbingFixtures,
				BuiltInCategory.OST_Sprinklers,
				BuiltInCategory.OST_DuctInsulations,
				BuiltInCategory.OST_PipeInsulations
			})).WhereElementIsNotElementType().ToList<Element>())
			{
				Parameter parameter = current.get_Parameter(BuiltInParameter.RBS_SYSTEM_NAME_PARAM);
				if (parameter != null)
				{
					string text = parameter.AsString();
					if (!string.IsNullOrEmpty(text) && (text.IndexOf(name, StringComparison.OrdinalIgnoreCase) >= 0 || name.IndexOf(text, StringComparison.OrdinalIgnoreCase) >= 0))
					{
						list.Add(current);
					}
				}
			}
			return list;
		}
	}
