		private string GetViewTypeName(Autodesk.Revit.DB.View view)
		{
			ViewType viewType = view.ViewType;
			switch (viewType)
			{
			case ViewType.FloorPlan:
				return "План этажа";
			case ViewType.CeilingPlan:
				return "План потолка";
			case ViewType.Elevation:
				return "Фасад";
			case ViewType.ThreeD:
				return "3D вид";
			default:
				switch (viewType)
				{
				case ViewType.EngineeringPlan:
					return "План несущих констр.";
				case ViewType.AreaPlan:
					return "План зонирования";
				case ViewType.Section:
					return "Разрез";
				case ViewType.Detail:
					return "Фрагмент";
				default:
					return view.ViewType.ToString();
				}
				break;
			}
		}
