		private void PopulateSourceViews(object activeView)
		{
			this._cbSourceView.Items.Clear();
			ViewItem viewItem = null;
			foreach (ViewItem current in this._sourceViews)
			{
				this._cbSourceView.Items.Add(current);
				if (activeView != null && current.RawView == activeView)
				{
					viewItem = current;
				}
			}
			if (viewItem != null)
			{
				this._cbSourceView.SelectedItem = viewItem;
				return;
			}
			if (this._cbSourceView.Items.Count > 0)
			{
				this._cbSourceView.SelectedIndex = 0;
			}
		}
		private void CbSourceView_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			object selectedSourceView = this.SelectedSourceView;
			if (selectedSourceView == null || this._onSourceViewChangedCallback == null)
			{
				return;
			}
			this._allFilters = this._onSourceViewChangedCallback(selectedSourceView);
			this.RefreshFiltersList();
		}
		private void RefreshFiltersList()
		{
			this._lstFilters.Items.Clear();
			using (List<FilterItem>.Enumerator enumerator = this._allFilters.GetEnumerator())
			{
				while (enumerator.MoveNext())
				{
					FilterItem item = enumerator.Current;
					System.Windows.Controls.Grid grid = new System.Windows.Controls.Grid
					{
						Margin = new Thickness(5.0, 2.0, 5.0, 2.0)
					};
					grid.ColumnDefinitions.Add(new ColumnDefinition
					{
						Width = new GridLength(30.0)
					});
					grid.ColumnDefinitions.Add(new ColumnDefinition
					{
						Width = new GridLength(1.0, GridUnitType.Star)
					});
					System.Windows.Controls.CheckBox checkBox = new System.Windows.Controls.CheckBox
					{
						VerticalAlignment = VerticalAlignment.Center,
						IsChecked = new bool?(item.IsChecked)
					};
					checkBox.Checked += delegate(object s, RoutedEventArgs e)
					{
						item.IsChecked = true;
					};
					checkBox.Unchecked += delegate(object s, RoutedEventArgs e)
					{
						item.IsChecked = false;
					};
					System.Windows.Controls.Grid.SetColumn(checkBox, 0);
					grid.Children.Add(checkBox);
					TextBlock element = new TextBlock
					{
						Text = item.Name,
						Foreground = System.Windows.Media.Brushes.White,
						VerticalAlignment = VerticalAlignment.Center
					};
					System.Windows.Controls.Grid.SetColumn(element, 1);
					grid.Children.Add(element);
					this._lstFilters.Items.Add(grid);
				}
			}
		}
