		private void BtnCopy_Click(object sender, RoutedEventArgs e)
		{
			if (this.SelectedSourceView == null)
			{
				System.Windows.MessageBox.Show("Пожалуйста, выберите исходный вид (донор).", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			if (this.SelectedFilters.Count == 0)
			{
				System.Windows.MessageBox.Show("Пожалуйста, выберите хотя бы один фильтр для копирования.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			if (this.SelectedTargetViews.Count == 0)
			{
				System.Windows.MessageBox.Show("Пожалуйста, выберите хотя бы один целевой вид (получатель).", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			this.IsCopyRequested = true;
			base.DialogResult = new bool?(true);
			base.Close();
		}
