	[Transaction(TransactionMode.Manual)]
	public class HeatLossCommand : IExternalCommand
	{
		public Result Execute(ExternalCommandData commandData, ref string message, ElementSet elements)
		{
			UIApplication application = commandData.Application;
			UIDocument activeUIDocument = application.ActiveUIDocument;
			Document doc = (activeUIDocument != null) ? activeUIDocument.Document : null;
			Document expr_33 = doc;
			Autodesk.Revit.DB.View view = (expr_33 != null) ? expr_33.ActiveView : null;
			if (doc == null || view == null)
			{
				message = "Не найден активный вид или документ.";
				return Result.Failed;
			}
			Result result;
			try
			{
				Logger.Log("Запуск команды расчета теплопотерь.", "INFO");
				List<SpatialElement> list = new FilteredElementCollector(doc, view.Id).OfCategory(BuiltInCategory.OST_Rooms).Cast<SpatialElement>().ToList<SpatialElement>();
				if (list.Count == 0)
				{
					list = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Rooms).Cast<SpatialElement>().ToList<SpatialElement>();
				}
				if (list.Count == 0)
				{
					TaskDialog.Show("Внимание", "В проекте не найдено помещений (Rooms) для расчета теплопотерь.");
					result = Result.Cancelled;
				}
				else
				{
					List<RoomHeatLossItem> list2 = new List<RoomHeatLossItem>();
					foreach (SpatialElement current in list)
					{
						Parameter expr_103 = current.get_Parameter(BuiltInParameter.ROOM_AREA);
						double num = (expr_103 != null) ? expr_103.AsDouble() : 0.0;
						Parameter expr_126 = current.get_Parameter(BuiltInParameter.ROOM_VOLUME);
						double arg_151_0 = (expr_126 != null) ? expr_126.AsDouble() : 0.0;
						double num2 = num * 0.092903;
						double value = arg_151_0 * 0.0283168;
						if (num2 > 0.0)
						{
							list2.Add(new RoomHeatLossItem
							{
								Number = current.Number,
								Name = current.Name,
								Area = Math.Round(num2, 2),
								Volume = Math.Round(value, 2),
								RawRoom = current
							});
						}
					}
					if (list2.Count == 0)
					{
						TaskDialog.Show("Внимание", "Найденные помещения имеют нулевую площадь. Проверьте границы помещений.");
						result = Result.Cancelled;
					}
					else
					{
						List<string> writableRoomDoubleParameters = HeatLossCommand.GetWritableRoomDoubleParameters(doc);
						HeatLossWindow window = new HeatLossWindow(list2, writableRoomDoubleParameters);
						new WindowInteropHelper(window).Owner = application.MainWindowHandle;
						window.CalculateRequested += delegate
						{
							this.PerformCalculation(window, doc);
						};
						window.WriteToRevitRequested += delegate
						{
							this.WriteBackToRevit(window, doc);
						};
						window.ExportExcelRequested += delegate
						{
							this.ExportToExcel(window, doc);
						};
						this.PerformCalculation(window, doc);
						window.ShowDialog();
						result = Result.Succeeded;
					}
				}
			}
			catch (Exception ex)
			{
				Logger.LogError("Ошибка в команде расчета теплопотерь", ex);
				message = ex.Message + "\n" + ex.StackTrace;
				result = Result.Failed;
			}
			return result;
		}
		private static List<string> GetWritableRoomDoubleParameters(Document doc)
		{
			List<string> list = new List<string>();
			Element element = new FilteredElementCollector(doc).OfCategory(BuiltInCategory.OST_Rooms).FirstOrDefault<Element>();
			if (element != null)
			{
				foreach (Parameter parameter in element.Parameters)
				{
					if (parameter.StorageType == StorageType.Double && !parameter.IsReadOnly)
					{
						list.Add(parameter.Definition.Name);
					}
				}
			}
			if (!list.Contains("Теплопотери"))
			{
				list.Insert(0, "Теплопотери");
			}
			return list.Distinct<string>().ToList<string>();
		}
		private void PerformCalculation(HeatLossWindow window, Document doc)
		{
			double arg_0E_0 = window.TempIndoor;
			double tempOutdoor = window.TempOutdoor;
			double num = arg_0E_0 - tempOutdoor;
			double uWallExt = window.UWallExt;
			double uWindow = window.UWindow;
			double uDoor = window.UDoor;
			double uRoof = window.URoof;
			double uFloor = window.UFloor;
			double airChanges = window.AirChanges;
			SpatialElementBoundaryOptions options = new SpatialElementBoundaryOptions();
			foreach (RoomHeatLossItem current in window.Rooms)
			{
				SpatialElement spatialElement = current.RawRoom as SpatialElement;
				if (spatialElement != null)
				{
					double area = current.Area;
					double volume = current.Volume;
					double num2 = 0.0;
					IList<IList<BoundarySegment>> boundarySegments = spatialElement.GetBoundarySegments(options);
					if (boundarySegments != null)
					{
						using (IEnumerator<IList<BoundarySegment>> enumerator2 = boundarySegments.GetEnumerator())
						{
							while (enumerator2.MoveNext())
							{
								foreach (BoundarySegment current2 in enumerator2.Current)
								{
									double num3 = current2.GetCurve().Length * 0.3048;
									double num4 = 3.0;
									try
									{
										Parameter expr_FE = spatialElement.get_Parameter(BuiltInParameter.ROOM_HEIGHT);
										double num5 = (expr_FE != null) ? expr_FE.AsDouble() : 0.0;
										if (num5 > 0.0)
										{
											num4 = num5 * 0.3048;
										}
									}
									catch
									{
									}
									double num6 = num3 * num4;
									ElementId elementId = ElementId.InvalidElementId;
									try
									{
										PropertyInfo property = current2.GetType().GetProperty("ElementId");
										if (property != null)
										{
											elementId = (property.GetValue(current2) as ElementId);
										}
										else
										{
											MethodInfo method = current2.GetType().GetMethod("GetElementId");
											if (method != null)
											{
												elementId = (method.Invoke(current2, null) as ElementId);
											}
										}
									}
									catch
									{
									}
									Element element = null;
									if (elementId != null && elementId != ElementId.InvalidElementId)
									{
										element = doc.GetElement(elementId);
									}
									double num7 = uWallExt;
									if (element != null)
									{
										Category expr_1DA = element.Category;
										string arg_1F2_0;
										if (expr_1DA == null)
										{
											arg_1F2_0 = null;
										}
										else
										{
											string expr_1E6 = expr_1DA.Name;
											arg_1F2_0 = ((expr_1E6 != null) ? expr_1E6.ToLower() : null);
										}
										string text = arg_1F2_0 ?? "";
										if (text.Contains("окно") || text.Contains("window"))
										{
											num7 = uWindow;
										}
										else
										{
											if (text.Contains("двер") || text.Contains("door"))
											{
												num7 = uDoor;
											}
											else
											{
												if (text.Contains("перекрыт") || text.Contains("roof") || text.Contains("крыш"))
												{
													num7 = uRoof;
												}
												else
												{
													if (text.Contains("пол") || text.Contains("floor"))
													{
														num7 = uFloor;
													}
													else
													{
														Wall wall = element as Wall;
														if (wall != null)
														{
															Parameter parameter = wall.WallType.get_Parameter(BuiltInParameter.FUNCTION_PARAM);
															if (parameter != null && parameter.HasValue && parameter.AsInteger() == 1)
															{
																num7 = 0.0;
															}
														}
													}
												}
											}
										}
									}
									num2 += num7 * num6 * num;
								}
							}
						}
					}
					if (num2 == 0.0)
					{
						num2 = area * 45.0;
					}
					double num8 = 0.337 * volume * airChanges * num;
					current.TransmissionLoss = Math.Round(num2, 1);
					current.VentilationLoss = Math.Round(num8, 1);
					current.TotalLoss = Math.Round(num2 + num8, 1);
				}
			}
		}
		private void WriteBackToRevit(HeatLossWindow window, Document doc)
		{
			string selectedParameter = window.SelectedParameter;
			if (string.IsNullOrEmpty(selectedParameter))
			{
				TaskDialog.Show("Ошибка", "Не выбран параметр для записи.");
				return;
			}
			RoomHeatLossItem expr_2B = window.Rooms.FirstOrDefault<RoomHeatLossItem>();
			SpatialElement spatialElement = ((expr_2B != null) ? expr_2B.RawRoom : null) as SpatialElement;
			if (spatialElement == null)
			{
				return;
			}
			Parameter parameter = spatialElement.LookupParameter(selectedParameter);
			if (parameter == null)
			{
				TaskDialog.Show("Внимание", "Параметр с именем '" + selectedParameter + "' не найден у помещений. Запись невозможна. Убедитесь, что параметр добавлен к категории Помещения.");
				return;
			}
			if (parameter.IsReadOnly)
			{
				TaskDialog.Show("Ошибка", "Параметр '" + selectedParameter + "' доступен только для чтения.");
				return;
			}
			using (Transaction transaction = new Transaction(doc, "Запись теплопотерь BimboClub"))
			{
				transaction.Start();
				int num = 0;
				foreach (RoomHeatLossItem current in window.Rooms)
				{
					SpatialElement spatialElement2 = current.RawRoom as SpatialElement;
					if (spatialElement2 != null)
					{
						Parameter parameter2 = spatialElement2.LookupParameter(selectedParameter);
						if (parameter2 != null)
						{
							parameter2.Set(current.TotalLoss);
							num++;
						}
					}
				}
				transaction.Commit();
				TaskDialog.Show("Успех", string.Format("Теплопотери успешно записаны в параметр '{0}' для {1} помещений.", selectedParameter, num));
			}
		}
		private void ExportToExcel(HeatLossWindow window, Document doc)
		{
			using (System.Windows.Forms.SaveFileDialog saveFileDialog = new System.Windows.Forms.SaveFileDialog
			{
				Title = "Экспорт теплопотерь в Excel - BimboClub Tools",
				Filter = "Excel Workbook (*.xml)|*.xml|Excel 97-2003 (*.xls)|*.xls",
				FileName = string.Concat(doc.Title.Split(System.IO.Path.GetInvalidFileNameChars())).Trim() + "_Теплопотери.xls",
				DefaultExt = "xls",
				AddExtension = true
			})
			{
				if (saveFileDialog.ShowDialog() == DialogResult.OK)
				{
					ExcelTable excelTable = new ExcelTable
					{
						SheetName = "Расчет теплопотерь"
					};
					excelTable.Headers = new List<string>
					{
						"Номер помещения",
						"Имя помещения",
						"Площадь (м²)",
						"Объем (м³)",
						"Трансмиссия (Вт)",
						"Вентиляция (Вт)",
						"Теплопотери всего (Вт)"
					};
					excelTable.NumericSumColumns.Add(2);
					excelTable.NumericSumColumns.Add(3);
					excelTable.NumericSumColumns.Add(4);
					excelTable.NumericSumColumns.Add(5);
					excelTable.NumericSumColumns.Add(6);
					foreach (RoomHeatLossItem current in window.Rooms)
					{
						excelTable.Rows.Add(new List<object>
						{
							current.Number,
							current.Name,
							current.Area,
							current.Volume,
							current.TransmissionLoss,
							current.VentilationLoss,
							current.TotalLoss
						});
					}
					ExcelWriter.Write(saveFileDialog.FileName, new List<ExcelTable>
					{
						excelTable
					});
					TaskDialog.Show("Успех", "Данные расчета теплопотерь успешно экспортированы в:\n" + saveFileDialog.FileName);
				}
			}
		}
	}
