	public static class Logger
	{
		private static string GetLogPath()
		{
			string text = System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "BimboClub", "Logs");
			if (!Directory.Exists(text))
			{
				Directory.CreateDirectory(text);
			}
			return System.IO.Path.Combine(text, "BimboClubTools.log");
		}
		public static void Log(string message, string level = "INFO")
		{
			try
			{
				string logPath = Logger.GetLogPath();
				string str = string.Format("[{0:yyyy-MM-dd HH:mm:ss}] [{1}] {2}", DateTime.Now, level, message);
				Type typeFromHandle = typeof(Logger);
				lock (typeFromHandle)
				{
					File.AppendAllText(logPath, str + Environment.NewLine);
				}
			}
			catch
			{
			}
		}
		public static void LogError(string message, Exception ex)
		{
			Logger.Log(string.Concat(new string[]
			{
				message,
				" | Exception: ",
				(ex != null) ? ex.Message : null,
				"\nStackTrace: ",
				(ex != null) ? ex.StackTrace : null
			}), "ERROR");
		}
	}
	[Transaction(TransactionMode.Manual)]
	public class LToolsRulesCommand : IExternalCommand
	{
		private static readonly HashSet<System.Windows.Forms.Control> _themedControls = new HashSet<System.Windows.Forms.Control>();
		private static System.Drawing.Image _btnPlayImage = null;
		private static System.Drawing.Image _btnPlusImage = null;
		private static System.Drawing.Image _btnGearImage = null;
		private static bool _imagesLoaded = false;
		public Result Execute(ExternalCommandData commandData, ref string message, ElementSet elements)
		{
			Result result;
			try
			{
				string text = System.IO.Path.Combine(System.IO.Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location), "LTools.dll");
				if (!File.Exists(text))
				{
					TaskDialog.Show("Ошибка", "Файл LTools.dll не найден в папке плагина:\n" + text);
					result = Result.Failed;
				}
				else
				{
					Type type = Assembly.LoadFrom(text).GetType("SAV.ParamRules.CmdRuler");
					if (type == null)
					{
						TaskDialog.Show("Ошибка", "Не найден класс SAV.ParamRules.CmdRuler в LTools.dll");
						result = Result.Failed;
					}
					else
					{
						IExternalCommand externalCommand = Activator.CreateInstance(type) as IExternalCommand;
						if (externalCommand == null)
						{
							TaskDialog.Show("Ошибка", "Класс SAV.ParamRules.CmdRuler не реализует интерфейс IExternalCommand");
							result = Result.Failed;
						}
						else
						{
							System.Windows.Forms.Timer timer = new System.Windows.Forms.Timer();
							timer.Interval = 50;
							int inactiveCount = 0;
							timer.Tick += delegate(object sender, EventArgs ev)
							{
								try
								{
									bool flag = false;
									List<System.Windows.Forms.Form> list = new List<System.Windows.Forms.Form>();
									foreach (System.Windows.Forms.Form item in System.Windows.Forms.Application.OpenForms)
									{
										list.Add(item);
									}
									foreach (System.Windows.Forms.Form current in list)
									{
										if (current.GetType().Namespace != null && current.GetType().Namespace.StartsWith("SAV.ParamRules"))
										{
											flag = true;
											LToolsRulesCommand.StyleControl(current);
										}
									}
									if (flag)
									{
										int inactiveCount = 0;
									}
									else
									{
										int inactiveCount = inactiveCount;
										inactiveCount++;
										if (inactiveCount > 100)
										{
											timer.Stop();
											timer.Dispose();
										}
									}
								}
								catch
								{
								}
							};
							timer.Start();
							result = externalCommand.Execute(commandData, ref message, elements);
						}
					}
				}
			}
			catch (Exception ex)
			{
				Logger.LogError("Ошибка при вызове редактора правил LTools", ex);
				message = ex.Message;
				result = Result.Failed;
			}
			return result;
		}
		private static void LoadButtonImages()
		{
			if (LToolsRulesCommand._imagesLoaded)
			{
				return;
			}
			try
			{
				string expr_18 = System.IO.Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location);
				string text = System.IO.Path.Combine(expr_18, "icon_btn_play.png");
				string text2 = System.IO.Path.Combine(expr_18, "icon_btn_plus.png");
				string text3 = System.IO.Path.Combine(expr_18, "icon_btn_gear.png");
				if (File.Exists(text))
				{
					LToolsRulesCommand._btnPlayImage = System.Drawing.Image.FromFile(text);
				}
				if (File.Exists(text2))
				{
					LToolsRulesCommand._btnPlusImage = System.Drawing.Image.FromFile(text2);
				}
				if (File.Exists(text3))
				{
					LToolsRulesCommand._btnGearImage = System.Drawing.Image.FromFile(text3);
				}
			}
			catch (Exception ex)
			{
				Logger.LogError("Error loading custom WinForms button images", ex);
			}
			finally
			{
				LToolsRulesCommand._imagesLoaded = true;
			}
		}
