		public Result Execute(ExternalCommandData commandData, ref string message, ElementSet elements)
		{
			UIApplication application = commandData.Application;
			Document document = application.ActiveUIDocument.Document;
			Result result;
			try
			{
				Logger.Log("Запуск команды Расстановка элементов по сети (Network Placer).", "INFO");
				IEnumerable<FamilySymbol> arg_5B_0 = new FilteredElementCollector(document).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>();
				Func<FamilySymbol, bool> arg_5B_1;
				if ((arg_5B_1 = PlacementCommand.<>c.<>9__0_0) == null)
				{
					arg_5B_1 = (PlacementCommand.<>c.<>9__0_0 = new Func<FamilySymbol, bool>(PlacementCommand.<>c.<>9.<Execute>b__0_0));
				}
				IEnumerable<FamilySymbol> arg_7F_0 = arg_5B_0.Where(arg_5B_1);
				Func<FamilySymbol, string> arg_7F_1;
				if ((arg_7F_1 = PlacementCommand.<>c.<>9__0_1) == null)
				{
					arg_7F_1 = (PlacementCommand.<>c.<>9__0_1 = new Func<FamilySymbol, string>(PlacementCommand.<>c.<>9.<Execute>b__0_1));
				}
				IOrderedEnumerable<FamilySymbol> arg_A3_0 = arg_7F_0.OrderBy(arg_7F_1);
				Func<FamilySymbol, string> arg_A3_1;
				if ((arg_A3_1 = PlacementCommand.<>c.<>9__0_2) == null)
				{
					arg_A3_1 = (PlacementCommand.<>c.<>9__0_2 = new Func<FamilySymbol, string>(PlacementCommand.<>c.<>9.<Execute>b__0_2));
				}
				List<FamilySymbol> list = arg_A3_0.ThenBy(arg_A3_1).ToList<FamilySymbol>();
				if (list.Count == 0)
				{
					TaskDialog.Show("Внимание", "В проекте не найдено загружаемых семейств для расстановки.");
					result = Result.Cancelled;
				}
				else
				{
					IEnumerable<FamilySymbol> arg_EE_0 = list;
					Func<FamilySymbol, BimboClub.SymbolItem> arg_EE_1;
					if ((arg_EE_1 = PlacementCommand.<>c.<>9__0_3) == null)
					{
						arg_EE_1 = (PlacementCommand.<>c.<>9__0_3 = new Func<FamilySymbol, BimboClub.SymbolItem>(PlacementCommand.<>c.<>9.<Execute>b__0_3));
					}
					PlacementWindow placementWindow = new PlacementWindow(arg_EE_0.Select(arg_EE_1).ToList<BimboClub.SymbolItem>());
					new WindowInteropHelper(placementWindow).Owner = application.MainWindowHandle;
					if (placementWindow.ShowDialog().GetValueOrDefault() && placementWindow.IsApplied)
					{
						FamilySymbol familySymbol = placementWindow.SelectedSymbol as FamilySymbol;
						if (familySymbol == null)
						{
							result = Result.Cancelled;
							return result;
						}
						List<Element> list2 = new List<Element>();
						if (placementWindow.ProcessDucts)
						{
							FilteredElementCollector filteredElementCollector = placementWindow.OnlyCurrentView ? new FilteredElementCollector(document, document.ActiveView.Id) : new FilteredElementCollector(document);
							list2.AddRange(filteredElementCollector.OfClass(typeof(Duct)).Cast<Element>());
						}
						if (placementWindow.ProcessPipes)
						{
							FilteredElementCollector filteredElementCollector2 = placementWindow.OnlyCurrentView ? new FilteredElementCollector(document, document.ActiveView.Id) : new FilteredElementCollector(document);
							list2.AddRange(filteredElementCollector2.OfClass(typeof(Pipe)).Cast<Element>());
						}
						if (placementWindow.ProcessTrays)
						{
							FilteredElementCollector filteredElementCollector3 = placementWindow.OnlyCurrentView ? new FilteredElementCollector(document, document.ActiveView.Id) : new FilteredElementCollector(document);
							list2.AddRange(filteredElementCollector3.OfClass(typeof(CableTray)).Cast<Element>());
						}
						if (list2.Count == 0)
						{
							TaskDialog.Show("Внимание", "Не найдено элементов выбранных сетей для расстановки.");
							result = Result.Cancelled;
							return result;
						}
						double num = placementWindow.SpacingMm / 304.8;
						double value = placementWindow.HOffsetMm / 304.8;
						double value2 = placementWindow.VOffsetMm / 304.8;
						int num2 = 0;
						using (Transaction transaction = new Transaction(document, "Расстановка элементов по сети BimboClub"))
						{
							transaction.Start();
							if (!familySymbol.IsActive)
							{
								familySymbol.Activate();
								document.Regenerate();
							}
							foreach (Element current in list2)
							{
								LocationCurve locationCurve = current.Location as LocationCurve;
								if (locationCurve != null && !(locationCurve.Curve == null))
								{
									Curve curve = locationCurve.Curve;
									double length = curve.Length;
									if (length > 0.001)
									{
										XYZ endPoint = curve.GetEndPoint(0);
										XYZ xYZ = (curve.GetEndPoint(1) - endPoint).Normalize();
										XYZ left;
										XYZ left2;
										if (Math.Abs(xYZ.Z) > 0.999)
										{
											left = XYZ.BasisX;
											left2 = XYZ.BasisY;
										}
										else
										{
											left = new XYZ(-xYZ.Y, xYZ.X, 0.0).Normalize();
											left2 = XYZ.BasisZ;
										}
										if (length <= num)
										{
											XYZ location = curve.Evaluate(0.5, true) + left * value + left2 * value2;
											try
											{
												document.Create.NewFamilyInstance(location, familySymbol, current, StructuralType.NonStructural);
												num2++;
												continue;
											}
											catch (Exception ex)
											{
												Logger.LogError(string.Format("Не удалось разместить элемент на сети {0}", current.Id), ex);
												continue;
											}
										}
										int num3 = (int)Math.Floor(length / num);
										if (num3 <= 0)
										{
											num3 = 1;
										}
										double num4 = length - (double)num3 * num;
										double num5 = num / 2.0 + num4 / 2.0;
										for (int i = 0; i < num3; i++)
										{
											double parameter = (num5 + (double)i * num) / length;
											XYZ location2 = curve.Evaluate(parameter, true) + left * value + left2 * value2;
											try
											{
												document.Create.NewFamilyInstance(location2, familySymbol, current, StructuralType.NonStructural);
												num2++;
											}
											catch (Exception ex2)
											{
												Logger.LogError(string.Format("Не удалось разместить элемент на сети {0}", current.Id), ex2);
											}
										}
									}
								}
							}
							transaction.Commit();
						}
						Logger.Log(string.Format("Успешно расставлено элементов по сети: {0}.", num2), "INFO");
						TaskDialog.Show("Успех", string.Format("Расстановка завершена!\nРазмещено элементов: {0}", num2));
					}
					result = Result.Succeeded;
				}
			}
			catch (Exception ex3)
			{
				Logger.LogError("Ошибка во время выполнения PlacementCommand", ex3);
				message = ex3.Message + "\n" + ex3.StackTrace;
				result = Result.Failed;
			}
			return result;
		}
