		private void ApplyButtonStyles(System.Windows.Controls.Button btn, LinearGradientBrush normalGrad, LinearGradientBrush hoverGrad, Style roundedStyle)
		{
			btn.Style = roundedStyle;
			btn.Background = normalGrad;
			btn.MouseEnter += delegate(object s, System.Windows.Input.MouseEventArgs e)
			{
				if (btn.IsEnabled)
				{
					btn.Background = hoverGrad;
				}
			};
			btn.MouseLeave += delegate(object s, System.Windows.Input.MouseEventArgs e)
			{
				if (btn.IsEnabled)
				{
					btn.Background = normalGrad;
				}
			};
			btn.IsEnabledChanged += delegate(object s, DependencyPropertyChangedEventArgs ev)
			{
				if (btn.IsEnabled)
				{
					btn.Background = normalGrad;
					return;
				}
				btn.Background = new SolidColorBrush(System.Windows.Media.Color.FromRgb(70, 70, 82));
			};
		}
		private void ApplyFlatButtonStyles(System.Windows.Controls.Button btn, SolidColorBrush normalBrush, SolidColorBrush hoverBrush, Style roundedStyle)
		{
			btn.Style = roundedStyle;
			btn.Background = normalBrush;
			btn.MouseEnter += delegate(object s, System.Windows.Input.MouseEventArgs e)
			{
				if (btn.IsEnabled)
				{
					btn.Background = hoverBrush;
				}
			};
			btn.MouseLeave += delegate(object s, System.Windows.Input.MouseEventArgs e)
			{
				if (btn.IsEnabled)
				{
					btn.Background = normalBrush;
				}
			};
		}
