		private void PopulateSymbols()
		{
			this._cbSymbols.Items.Clear();
			foreach (BimboClub.SymbolItem current in this._symbols)
			{
				this._cbSymbols.Items.Add(current);
			}
			if (this._cbSymbols.Items.Count > 0)
			{
				this._cbSymbols.SelectedIndex = 0;
			}
		}
		private void BtnApply_Click(object sender, RoutedEventArgs e)
		{
			if (this.SelectedSymbol == null)
			{
				System.Windows.MessageBox.Show("Пожалуйста, выберите размещаемое семейство.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			if (!this.ProcessDucts && !this.ProcessPipes && !this.ProcessTrays)
			{
				System.Windows.MessageBox.Show("Пожалуйста, выберите хотя бы один тип сетей для расстановки.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			if (this.SpacingMm <= 0.0)
			{
				System.Windows.MessageBox.Show("Пожалуйста, введите положительный шаг расстановки.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			this.IsApplied = true;
			base.DialogResult = new bool?(true);
			base.Close();
		}
	}
