		private void ShowSuccessAndPromptOpenFolder(string content, string folderPath)
		{
			try
			{
				if (new TaskDialog("Экспорт завершен")
				{
					MainInstruction = "Экспорт успешно завершен!",
					MainContent = content + "\n\nСохранено в:\n" + folderPath + "\n\nЖелаете открыть папку с результатами?",
					CommonButtons = TaskDialogCommonButtons.Yes | TaskDialogCommonButtons.No,
					DefaultButton = TaskDialogResult.Yes
				}.Show() == TaskDialogResult.Yes)
				{
					Process.Start(new ProcessStartInfo
					{
						FileName = folderPath,
						UseShellExecute = true
					});
				}
			}
			catch (Exception ex)
			{
				Logger.LogError("Не удалось показать диалог или открыть папку", ex);
			}
		}
		private string GetSheetSection(ViewSheet sheet)
		{
			foreach (Parameter parameter in sheet.Parameters)
			{
				if (parameter.Definition != null)
				{
					string name = parameter.Definition.Name;
					if ((name.Contains("Раздел") || name.Contains("раздел") || name.Contains("Штамп")) && parameter.StorageType == StorageType.String)
					{
						string text = parameter.AsString();
						if (!string.IsNullOrEmpty(text))
						{
							return text;
						}
					}
				}
			}
			return "ОВ";
		}
		private string MakeValidFileName(string name)
		{
			char[] invalidFileNameChars = System.IO.Path.GetInvalidFileNameChars();
			for (int i = 0; i < invalidFileNameChars.Length; i++)
			{
				char oldChar = invalidFileNameChars[i];
				name = name.Replace(oldChar, '_');
			}
			return name;
		}
