		private void PopulateFamilies()
		{
			if (this._preselectedFamily != null)
			{
				FamilyItem familyItem = this._families.FirstOrDefault((FamilyItem f) => f.RawFamily == this._preselectedFamily);
				if (familyItem != null)
				{
					this._lblCurrentFamilyStatic.Text = familyItem.Name;
					this._txtNewName.Text = familyItem.Name;
					this._txtNewName.Focus();
					this._txtNewName.SelectAll();
					return;
				}
			}
			else
			{
				this._cbFamilies.Items.Clear();
				foreach (FamilyItem current in this._families)
				{
					this._cbFamilies.Items.Add(current);
				}
				if (this._cbFamilies.Items.Count > 0)
				{
					this._cbFamilies.SelectedIndex = 0;
				}
			}
		}
		private void CbFamilies_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			FamilyItem familyItem = this._cbFamilies.SelectedItem as FamilyItem;
			if (familyItem != null)
			{
				this._txtNewName.Text = familyItem.Name;
				this._txtNewName.Focus();
				this._txtNewName.SelectAll();
			}
		}
		private void TxtNewName_KeyDown(object sender, System.Windows.Input.KeyEventArgs e)
		{
			if (e.Key == Key.Return)
			{
				this.BtnRename_Click(this, new RoutedEventArgs());
			}
		}
		private void BtnRename_Click(object sender, RoutedEventArgs e)
		{
			if (this.SelectedFamily == null)
			{
				System.Windows.MessageBox.Show("Пожалуйста, выберите семейство для переименования.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			if (string.IsNullOrWhiteSpace(this.NewName))
			{
				System.Windows.MessageBox.Show("Пожалуйста, введите корректное новое имя семейства.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			this.IsRenameRequested = true;
			base.DialogResult = new bool?(true);
			base.Close();
		}
		private void BtnDelete_Click(object sender, RoutedEventArgs e)
		{
			if (this.SelectedFamily == null)
			{
				System.Windows.MessageBox.Show("Пожалуйста, выберите семейство для удаления.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			this.IsDeleteRequested = true;
			base.DialogResult = new bool?(true);
			base.Close();
		}
	}
