		private Element CreateMepCurve(Document doc, bool isDuct, ElementId systemTypeId, ElementId typeId, ElementId levelId, XYZ start, XYZ end, double w, double h, double d)
		{
			Element result;
			if (isDuct)
			{
				Duct duct = Duct.Create(doc, systemTypeId, typeId, levelId, start, end);
				result = duct;
				if (w > 0.0 && h > 0.0)
				{
					duct.get_Parameter(BuiltInParameter.RBS_CURVE_WIDTH_PARAM).Set(w);
					duct.get_Parameter(BuiltInParameter.RBS_CURVE_HEIGHT_PARAM).Set(h);
				}
				else
				{
					if (d > 0.0)
					{
						duct.get_Parameter(BuiltInParameter.RBS_CURVE_DIAMETER_PARAM).Set(d);
					}
				}
			}
			else
			{
				Pipe pipe = Pipe.Create(doc, systemTypeId, typeId, levelId, start, end);
				result = pipe;
				if (d > 0.0)
				{
					pipe.get_Parameter(BuiltInParameter.RBS_PIPE_DIAMETER_PARAM).Set(d);
				}
			}
			return result;
		}
		private Connector GetConnectorNearPoint(Element elem, XYZ pt)
		{
			ConnectorManager connectorManager = null;
			if (elem is Duct)
			{
				connectorManager = ((Duct)elem).ConnectorManager;
			}
			else
			{
				if (elem is Pipe)
				{
					connectorManager = ((Pipe)elem).ConnectorManager;
				}
			}
			if (connectorManager == null)
			{
				return null;
			}
			Connector result = null;
			double num = 1.7976931348623157E+308;
			foreach (Connector connector in connectorManager.Connectors)
			{
				double num2 = connector.Origin.DistanceTo(pt);
				if (num2 < num)
				{
					num = num2;
					result = connector;
				}
			}
			return result;
		}
		private List<ObstacleInfo> FindObstacles(Document doc, Autodesk.Revit.DB.Line mepLine, bool includeLinks)
		{
			List<ObstacleInfo> list = new List<ObstacleInfo>();
			ElementMulticategoryFilter filter = new ElementMulticategoryFilter(new List<BuiltInCategory>
			{
				BuiltInCategory.OST_Walls,
				BuiltInCategory.OST_StructuralColumns,
				BuiltInCategory.OST_StructuralFraming,
				BuiltInCategory.OST_Floors
			});
			BoundingBoxXYZ boundingBoxXYZ = new BoundingBoxXYZ();
			XYZ endPoint = mepLine.GetEndPoint(0);
			XYZ endPoint2 = mepLine.GetEndPoint(1);
			boundingBoxXYZ.Min = new XYZ(Math.Min(endPoint.X, endPoint2.X) - 1.0, Math.Min(endPoint.Y, endPoint2.Y) - 1.0, Math.Min(endPoint.Z, endPoint2.Z) - 1.0);
			boundingBoxXYZ.Max = new XYZ(Math.Max(endPoint.X, endPoint2.X) + 1.0, Math.Max(endPoint.Y, endPoint2.Y) + 1.0, Math.Max(endPoint.Z, endPoint2.Z) + 1.0);
			BoundingBoxIntersectsFilter filter2 = new BoundingBoxIntersectsFilter(new Outline(boundingBoxXYZ.Min, boundingBoxXYZ.Max));
			foreach (Element current in new FilteredElementCollector(doc).WherePasses(filter).WherePasses(filter2).WhereElementIsNotElementType())
			{
				list.Add(new ObstacleInfo(current, Autodesk.Revit.DB.Transform.Identity));
			}
			if (includeLinks)
			{
				foreach (RevitLinkInstance current2 in new FilteredElementCollector(doc).OfClass(typeof(RevitLinkInstance)).Cast<RevitLinkInstance>())
				{
					Document linkDocument = current2.GetLinkDocument();
					if (linkDocument != null)
					{
						Autodesk.Revit.DB.Transform totalTransform = current2.GetTotalTransform();
						Autodesk.Revit.DB.Transform expr_1D6 = totalTransform.Inverse;
						XYZ xYZ = expr_1D6.OfPoint(endPoint);
						XYZ xYZ2 = expr_1D6.OfPoint(endPoint2);
						BoundingBoxIntersectsFilter filter3 = new BoundingBoxIntersectsFilter(new Outline(new XYZ(Math.Min(xYZ.X, xYZ2.X) - 1.0, Math.Min(xYZ.Y, xYZ2.Y) - 1.0, Math.Min(xYZ.Z, xYZ2.Z) - 1.0), new XYZ(Math.Max(xYZ.X, xYZ2.X) + 1.0, Math.Max(xYZ.Y, xYZ2.Y) + 1.0, Math.Max(xYZ.Z, xYZ2.Z) + 1.0)));
						foreach (Element current3 in new FilteredElementCollector(linkDocument).WherePasses(filter).WherePasses(filter3).WhereElementIsNotElementType())
						{
							list.Add(new ObstacleInfo(current3, totalTransform));
						}
					}
				}
			}
			return list;
		}
		private bool GetClashGeometry(Autodesk.Revit.DB.Line mepLine, List<ObstacleInfo> obstacles, out XYZ center, out double width)
		{
			center = null;
			width = 0.0;
			XYZ endPoint = mepLine.GetEndPoint(0);
			(mepLine.GetEndPoint(1) - endPoint).Normalize();
			List<double> list = new List<double>();
			foreach (ObstacleInfo current in obstacles)
			{
				GeometryElement geometryElement = current.Element.get_Geometry(new Options
				{
					DetailLevel = ViewDetailLevel.Medium
				});
				Autodesk.Revit.DB.Transform transform = current.Transform;
				if (!(geometryElement == null))
				{
					using (IEnumerator<GeometryObject> enumerator2 = geometryElement.GetEnumerator())
					{
						while (enumerator2.MoveNext())
						{
							Solid solid = enumerator2.Current as Solid;
							if (solid != null && solid.Volume > 0.0)
							{
								if (!transform.IsIdentity)
								{
									solid = SolidUtils.CreateTransformed(solid, transform);
								}
								IEnumerator enumerator3 = solid.Faces.GetEnumerator();
								try
								{
									while (enumerator3.MoveNext())
									{
										IntersectionResultArray intersectionResultArray;
										if (((Face)enumerator3.Current).Intersect(mepLine, out intersectionResultArray) == SetComparisonResult.Overlap && intersectionResultArray != null)
										{
											foreach (IntersectionResult intersectionResult in intersectionResultArray)
											{
												double parameter = mepLine.Project(intersectionResult.XYZPoint).Parameter;
												list.Add(parameter);
											}
										}
									}
								}
								finally
								{
									IDisposable disposable = enumerator3 as IDisposable;
									if (disposable != null)
									{
										disposable.Dispose();
									}
								}
							}
						}
					}
				}
			}
			if (list.Count >= 2)
			{
				double num = list.Min();
				double num2 = list.Max();
				if (num >= 0.0 && num2 <= 1.0 && num < num2)
				{
					XYZ xYZ = mepLine.Evaluate(num, true);
					XYZ xYZ2 = mepLine.Evaluate(num2, true);
					center = xYZ + (xYZ2 - xYZ) * 0.5;
					width = xYZ.DistanceTo(xYZ2);
					return true;
				}
			}
			return false;
		}
