		private void BtnRun_Click(object sender, RoutedEventArgs e)
		{
			if (this.ClearanceMm <= 0.0)
			{
				System.Windows.MessageBox.Show("Пожалуйста, укажите положительный зазор.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			if (this.OffsetMm <= 0.0)
			{
				System.Windows.MessageBox.Show("Пожалуйста, укажите положительную высоту смещения.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			this.IsExecutionRequested = true;
			base.DialogResult = new bool?(true);
			base.Close();
		}
