			{
				Logger.Log("Запуск команды Расчет сечений (Sizer).", "INFO");
				IEnumerable<ElementId> arg_35_0 = activeUIDocument.Selection.GetElementIds();
				List<MEPCurve> list = new List<MEPCurve>();
				foreach (ElementId current in arg_35_0)
				{
					MEPCurve mEPCurve = document.GetElement(current) as MEPCurve;
					if (mEPCurve != null)
					{
						list.Add(mEPCurve);
					}
				}
				bool flag = list.Count > 0;
				string categoryName = "";
				double initialFlow = 0.0;
				double initialSizeVal = 0.0;
				double initialSizeVal2 = 0.0;
				if (flag)
				{
					MEPCurve mEPCurve2 = list.First<MEPCurve>();
					categoryName = mEPCurve2.Category.Name;
					Parameter parameter = null;
					if (mEPCurve2 is Duct)
					{
						parameter = mEPCurve2.get_Parameter(BuiltInParameter.RBS_DUCT_FLOW_PARAM);
					}
					else
					{
						if (mEPCurve2 is Pipe)
						{
							parameter = mEPCurve2.get_Parameter(BuiltInParameter.RBS_PIPE_FLOW_PARAM);
						}
					}
					if (parameter != null && parameter.HasValue)
					{
						double num = parameter.AsDouble();
						if (mEPCurve2 is Duct)
						{
							initialFlow = num * 101.940647;
						}
						else
						{
							initialFlow = num * 28.3168466;
						}
					}
					Duct duct = mEPCurve2 as Duct;
					if (duct != null)
					{
						Parameter parameter2 = duct.get_Parameter(BuiltInParameter.RBS_CURVE_DIAMETER_PARAM);
						Parameter parameter3 = duct.get_Parameter(BuiltInParameter.RBS_CURVE_WIDTH_PARAM);
						Parameter parameter4 = duct.get_Parameter(BuiltInParameter.RBS_CURVE_HEIGHT_PARAM);
						if (parameter2 != null && parameter2.HasValue)
						{
							initialSizeVal = parameter2.AsDouble() * 304.8;
						}
						else
						{
							if (parameter3 != null && parameter4 != null && parameter3.HasValue && parameter4.HasValue)
							{
								initialSizeVal = parameter3.AsDouble() * 304.8;
								initialSizeVal2 = parameter4.AsDouble() * 304.8;
							}
						}
					}
