					{
						Pipe pipe = mEPCurve2 as Pipe;
						if (pipe != null)
						{
							Parameter parameter5 = pipe.get_Parameter(BuiltInParameter.RBS_CURVE_DIAMETER_PARAM);
							if (parameter5 != null)
							{
								initialSizeVal = parameter5.AsDouble() * 304.8;
							}
						}
					}
