				{
					int num2 = 0;
					using (Transaction transaction = new Transaction(document, "Расчет сечений BimboClub"))
					{
						transaction.Start();
						foreach (MEPCurve current2 in list)
						{
							try
							{
								Duct duct2 = current2 as Duct;
								if (duct2 != null)
								{
									Parameter parameter6 = duct2.get_Parameter(BuiltInParameter.RBS_CURVE_DIAMETER_PARAM);
									Parameter parameter7 = duct2.get_Parameter(BuiltInParameter.RBS_CURVE_WIDTH_PARAM);
									Parameter parameter8 = duct2.get_Parameter(BuiltInParameter.RBS_CURVE_HEIGHT_PARAM);
									if (parameter6 != null && !parameter6.IsReadOnly && sizerWindow.FinalDiameter > 0.0)
									{
										parameter6.Set(sizerWindow.FinalDiameter / 304.8);
										num2++;
									}
									else
									{
										if (parameter7 != null && !parameter7.IsReadOnly && parameter8 != null && !parameter8.IsReadOnly && sizerWindow.FinalWidth > 0.0 && sizerWindow.FinalHeight > 0.0)
										{
											parameter7.Set(sizerWindow.FinalWidth / 304.8);
											parameter8.Set(sizerWindow.FinalHeight / 304.8);
											num2++;
										}
									}
								}
								else
								{
									Pipe pipe2 = current2 as Pipe;
									if (pipe2 != null && sizerWindow.FinalDiameter > 0.0)
									{
										Parameter parameter9 = pipe2.get_Parameter(BuiltInParameter.RBS_CURVE_DIAMETER_PARAM);
										if (parameter9 != null && !parameter9.IsReadOnly)
										{
											parameter9.Set(sizerWindow.FinalDiameter / 304.8);
											num2++;
										}
									}
								}
							}
							catch (Exception ex)
							{
								Logger.LogError(string.Format("Не удалось изменить размер элемента {0}", current2.Id), ex);
							}
						}
						transaction.Commit();
					}
					Logger.Log(string.Format("Успешно пересчитаны сечения для элементов: {0} из {1}.", num2, list.Count), "INFO");
					TaskDialog.Show("Успех", string.Format("Сечения успешно пересчитаны!\nИзменено элементов: {0} из {1}", num2, list.Count));
				}
