		private void SetSystemType(SizerWindow.SystemType sysType)
		{
			this._currentSystemType = sysType;
			if (this._currentSystemType == SizerWindow.SystemType.Duct)
			{
				this._lblFlowUnit.Content = "м³/ч";
				this._lblVelUnit.Content = "м/с";
				this._sliderVelocity.Minimum = 1.0;
				this._sliderVelocity.Maximum = 12.0;
				if (this._sliderVelocity.Value < 1.0 || this._sliderVelocity.Value > 12.0)
				{
					this._sliderVelocity.Value = 4.0;
				}
				this._rbRect.IsEnabled = true;
			}
			else
			{
				this._lblFlowUnit.Content = "л/с";
				this._lblVelUnit.Content = "м/с";
				this._sliderVelocity.Minimum = 0.1;
				this._sliderVelocity.Maximum = 3.0;
				if (this._sliderVelocity.Value < 0.1 || this._sliderVelocity.Value > 3.0)
				{
					this._sliderVelocity.Value = 1.0;
				}
				this._rbRound.IsChecked = new bool?(true);
				this._rbRect.IsEnabled = false;
				this.SetShapeType(SizerWindow.ShapeType.Round);
			}
			this.PopulateDiameterComboBox();
			this.Recalculate();
		}
		private void SetShapeType(SizerWindow.ShapeType shapeType)
		{
			this._currentShapeType = shapeType;
			if (this._currentShapeType == SizerWindow.ShapeType.Round)
			{
				this._txtCalcDiameter.Visibility = System.Windows.Visibility.Visible;
				this._cbStdDiameter.Visibility = System.Windows.Visibility.Visible;
				this._rectGrid.Visibility = System.Windows.Visibility.Collapsed;
			}
			else
			{
				this._txtCalcDiameter.Visibility = System.Windows.Visibility.Collapsed;
				this._cbStdDiameter.Visibility = System.Windows.Visibility.Collapsed;
				this._rectGrid.Visibility = System.Windows.Visibility.Visible;
				this.UpdateRectLabels();
			}
			this.Recalculate();
		}
		private void UpdateRectLabels()
		{
			if (this._rbLockWidth.IsChecked.GetValueOrDefault())
			{
				this._lblLockDim.Content = "Ширина зафиксир. (A):";
				this._lblFreeDim.Content = "Высота расчетная (B):";
				return;
			}
			this._lblLockDim.Content = "Высота зафиксир. (B):";
			this._lblFreeDim.Content = "Ширина расчетная (A):";
		}
		private void PopulateDiameterComboBox()
		{
			this._cbStdDiameter.Items.Clear();
			this._cbStdFreeDimension.Items.Clear();
			List<int> list;
			if (this._currentSystemType == SizerWindow.SystemType.Duct)
			{
				list = new List<int>
				{
					100,
					125,
					150,
					160,
					200,
					250,
					315,
					355,
					400,
					450,
					500,
					560,
					630,
					710,
					800,
					900,
					1000,
					1120,
					1250
				};
			}
			else
			{
				list = new List<int>
				{
					10,
					15,
					20,
					25,
					32,
					40,
					50,
					65,
					80,
					100,
					125,
					150,
					200,
					250,
					300
