			{
				this._txtVelocity.Text = this._sliderVelocity.Value.ToString("F1");
				this.Recalculate();
			}
		}
		private void TxtVelocity_TextChanged(object sender, TextChangedEventArgs e)
		{
			double num;
			if (double.TryParse(this._txtVelocity.Text, out num) && num >= this._sliderVelocity.Minimum && num <= this._sliderVelocity.Maximum)
			{
				this._sliderVelocity.Value = num;
				this.Recalculate();
			}
		}
		private void Recalculate()
		{
			if (this._txtFlow == null || this._txtVelocity == null)
			{
				return;
			}
			double num;
			if (!double.TryParse(this._txtFlow.Text, out num) || num <= 0.0)
			{
				return;
			}
			double num2;
			if (!double.TryParse(this._txtVelocity.Text, out num2) || num2 <= 0.0)
			{
				return;
			}
			if (this._currentSystemType == SizerWindow.SystemType.Duct)
			{
				double num3 = num / 3600.0 / num2;
				if (this._currentShapeType == SizerWindow.ShapeType.Round)
				{
					double num4 = Math.Sqrt(4.0 * num3 / 3.1415926535897931) * 1000.0;
					this._txtCalcDiameter.Text = string.Format("{0:F1} мм", num4);
					int num5 = 100;
					IEnumerator enumerator = ((IEnumerable)this._cbStdDiameter.Items).GetEnumerator();
					try
					{
						while (enumerator.MoveNext())
						{
							int num6 = int.Parse(enumerator.Current.ToString());
							if ((double)num6 >= num4)
							{
								num5 = num6;
								break;
							}
							num5 = num6;
						}
					}
					finally
					{
						IDisposable disposable = enumerator as IDisposable;
						if (disposable != null)
						{
							disposable.Dispose();
						}
					}
					this._cbStdDiameter.Text = num5.ToString();
				}
				else
				{
					double num7;
					if (!double.TryParse(this._txtLockedDimension.Text, out num7) || num7 <= 0.0)
					{
						return;
					}
					double num8 = num3 / (num7 / 1000.0) * 1000.0;
					this._txtCalcFreeDimension.Text = string.Format("{0:F1} мм", num8);
					int num9 = 100;
					IEnumerator enumerator = ((IEnumerable)this._cbStdFreeDimension.Items).GetEnumerator();
					try
					{
						while (enumerator.MoveNext())
						{
							int num10 = int.Parse(enumerator.Current.ToString());
							if ((double)num10 >= num8)
							{
								num9 = num10;
								break;
							}
							num9 = num10;
						}
					}
					finally
					{
						IDisposable disposable = enumerator as IDisposable;
						if (disposable != null)
						{
							disposable.Dispose();
						}
					}
					this._cbStdFreeDimension.Text = num9.ToString();
				}
			}
			else
			{
				double num11 = num / 1000.0 / num2;
				double num12 = Math.Sqrt(4.0 * num11 / 3.1415926535897931) * 1000.0;
				this._txtCalcDiameter.Text = string.Format("{0:F1} мм", num12);
				int num13 = 15;
				IEnumerator enumerator = ((IEnumerable)this._cbStdDiameter.Items).GetEnumerator();
				try
				{
					while (enumerator.MoveNext())
					{
						int num14 = int.Parse(enumerator.Current.ToString());
						if ((double)num14 >= num12)
						{
							num13 = num14;
							break;
						}
						num13 = num14;
					}
				}
				finally
				{
					IDisposable disposable = enumerator as IDisposable;
					if (disposable != null)
					{
						disposable.Dispose();
					}
				}
				this._cbStdDiameter.Text = num13.ToString();
			}
			this.RecalculateActuals();
		}
		private void RecalculateActuals()
		{
			if (this._txtActualVelocity == null || this._txtActualFlow == null)
			{
				return;
			}
			double num;
			if (!double.TryParse(this._txtFlow.Text, out num) || num <= 0.0)
			{
				return;
			}
			if (this._currentSystemType == SizerWindow.SystemType.Duct)
			{
				if (this._currentShapeType == SizerWindow.ShapeType.Round)
				{
					double num2;
					if (!double.TryParse(this._cbStdDiameter.Text, out num2) || num2 <= 0.0)
					{
						return;
					}
					double num3 = 3.1415926535897931 * Math.Pow(num2 / 2000.0, 2.0);
					double num4 = num / 3600.0 / num3;
					this._txtActualVelocity.Text = string.Format("{0:F2} м/с", num4);
					this._txtActualFlow.Text = string.Format("{0:F0} м³/ч", num);
					return;
				}
				else
				{
					double num5;
					if (!double.TryParse(this._txtLockedDimension.Text, out num5) || num5 <= 0.0)
					{
						return;
					}
					double num6;
					if (!double.TryParse(this._cbStdFreeDimension.Text, out num6) || num6 <= 0.0)
					{
						return;
					}
					double num7 = num5 / 1000.0 * (num6 / 1000.0);
					double num8 = num / 3600.0 / num7;
					this._txtActualVelocity.Text = string.Format("{0:F2} м/с", num8);
					this._txtActualFlow.Text = string.Format("{0:F0} м³/ч", num);
					return;
				}
			}
			else
			{
				double num9;
				if (!double.TryParse(this._cbStdDiameter.Text, out num9) || num9 <= 0.0)
				{
					return;
				}
				double num10 = 3.1415926535897931 * Math.Pow(num9 / 2000.0, 2.0);
				double num11 = num / 1000.0 / num10;
				this._txtActualVelocity.Text = string.Format("{0:F2} м/с", num11);
				this._txtActualFlow.Text = string.Format("{0:F2} л/с", num);
				return;
			}
		}
		private void BtnApply_Click(object sender, RoutedEventArgs e)
		{
			if (!this._hasSelectedElements)
			{
				System.Windows.MessageBox.Show("Режим калькулятора. Выберите элементы в модели Revit перед запуском, чтобы применить размеры.", "Автономный режим", MessageBoxButton.OK, MessageBoxImage.Asterisk);
				return;
			}
			if (this._currentSystemType == SizerWindow.SystemType.Duct)
			{
				if (this._currentShapeType == SizerWindow.ShapeType.Round)
				{
					double finalDiameter;
					if (double.TryParse(this._cbStdDiameter.Text, out finalDiameter))
					{
						this.FinalDiameter = finalDiameter;
					}
				}
				else
				{
					double num;
					double num2;
					if (double.TryParse(this._txtLockedDimension.Text, out num) && double.TryParse(this._cbStdFreeDimension.Text, out num2))
					{
						if (this._rbLockWidth.IsChecked.GetValueOrDefault())
						{
							this.FinalWidth = num;
							this.FinalHeight = num2;
						}
						else
						{
							this.FinalWidth = num2;
							this.FinalHeight = num;
						}
					}
				}
			}
			else
			{
				double finalDiameter2;
				if (double.TryParse(this._cbStdDiameter.Text, out finalDiameter2))
				{
					this.FinalDiameter = finalDiameter2;
				}
			}
			this.IsApplied = true;
			base.DialogResult = new bool?(true);
			base.Close();
		}
	}
