		private string GetElementSystemName(Element elem)
		{
			Parameter parameter = elem.get_Parameter(BuiltInParameter.RBS_SYSTEM_NAME_PARAM);
			if (parameter != null && !string.IsNullOrEmpty(parameter.AsString()))
			{
				return parameter.AsString();
			}
			return "Не в системе";
		}
		private string GetElementFamilyTypeName(Element elem)
		{
			if (elem is MEPCurve)
			{
				return elem.Name;
			}
			ElementId typeId = elem.GetTypeId();
			if (typeId != ElementId.InvalidElementId)
			{
				Element element = elem.Document.GetElement(typeId);
				if (element != null)
				{
					return elem.Name + " (" + element.Name + ")";
				}
			}
			return elem.Name;
		}
		private string GetParamString(Element elem, string paramName, string fallback = "—")
		{
			Parameter parameter = elem.LookupParameter(paramName);
			if (parameter != null && parameter.HasValue)
			{
				if (parameter.StorageType == StorageType.String)
				{
					string text = parameter.AsString();
					if (!string.IsNullOrWhiteSpace(text))
					{
						return text;
					}
				}
				else
				{
					if (parameter.StorageType == StorageType.Double)
					{
						return parameter.AsDouble().ToString("F2");
					}
					if (parameter.StorageType == StorageType.Integer)
					{
						return parameter.AsInteger().ToString();
					}
					if (parameter.StorageType == StorageType.ElementId)
					{
						ElementId elementId = parameter.AsElementId();
						if (elementId != ElementId.InvalidElementId)
						{
							Element element = elem.Document.GetElement(elementId);
							if (element != null)
							{
								return element.Name;
							}
						}
					}
				}
			}
			return fallback;
		}
		private void SetParamValue(Parameter p, double val)
		{
			if (p.StorageType == StorageType.Double)
			{
				p.Set(val);
				return;
			}
			if (p.StorageType == StorageType.Integer)
			{
				p.Set((int)Math.Round(val));
				return;
			}
			if (p.StorageType == StorageType.String)
			{
				p.Set(val.ToString("F2"));
			}
		}
