		private void BtnGenerate_Click(object sender, RoutedEventArgs e)
		{
			if (!this.IncludeDucts && !this.IncludePipes && !this.IncludeDuctFittings && !this.IncludePipeFittings && !this.IncludeDuctAccessories && !this.IncludePipeAccessories && !this.IncludeEquipment && !this.IncludePlumbing)
			{
				System.Windows.MessageBox.Show("Пожалуйста, выберите хотя бы одну категорию для спецификации.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			if (string.IsNullOrEmpty(this.ParamPosition) || string.IsNullOrEmpty(this.ParamName) || string.IsNullOrEmpty(this.ParamMark) || string.IsNullOrEmpty(this.ParamCode) || string.IsNullOrEmpty(this.ParamManufacturer) || string.IsNullOrEmpty(this.ParamUnit) || string.IsNullOrEmpty(this.ParamQuantity) || string.IsNullOrEmpty(this.ParamWeight) || string.IsNullOrEmpty(this.ParamNote))
			{
				System.Windows.MessageBox.Show("Пожалуйста, убедитесь, что все сопоставления параметров ГОСТ заполнены.", "Внимание", MessageBoxButton.OK, MessageBoxImage.Exclamation);
				return;
			}
			this.IsGenerationRequested = true;
			base.DialogResult = new bool?(true);
			base.Close();
		}
	}
